&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;阅读时间 : 22 minutes&lt;/div&gt;
&lt;p&gt;我经常被问到我的AI消耗成本是多少。我回答「每月20块钱」，然后对方会用圆睁的眼神看着我。于是今天，我为大家打开黑盒。本文是我73天vibe coding的完整审计：从OpenCode的SQLite数据库提取数据的方法论、查询表的SQL代码，以及与市场上*所有*供应商——西方和中国的——进行的详尽对比。结果如此不对称，以至于我不得不核查了三次计算。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;dlist&quot;&gt;
&lt;dl&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;抽动&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;&amp;lt;/think&amp;gt;&lt;/p&gt;
&lt;/dd&gt;
&lt;/dl&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_理解_stack谁负责做什么&quot;&gt;理解 Stack：谁负责做什么？&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;在深入数字之前，先澄清一下架构。我的设置中有三个不同的参与者，切勿将它们混淆：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontSize 12

title 我的LLM堆栈的三位演员
left to right direction

actor &quot;我 (开发者)&quot; as Dev

package &quot;OpenCode\n(github.com/anomalyco/opencode)&quot; as OC {
  rectangle &quot;CLI 的 vibe 编码
开源，免费&quot; as CLI
  note right of CLI
    C&#39;est l&#39;outil que j&#39;utilise
    pour coder avec des agents IA.
    Il ne fournit AUCUN modèle.
    C&#39;est un terminal + un orchestrateur.
  end note
}

package &quot;Ollama (本地安装)&quot; as OL {
  rectangle &quot;推理客户端
已安装在我的机器上&quot; as Client
  note right of Client
    C&#39;est le logiciel qui fait tourner
    les modèles. Il peut les exécuter
    en local OU les déléguer au cloud
    selon le tag (:cloud).
    Il s&#39;authentifie via clé SSH.
  end note
}

package &quot;Ollama 云
(ollama.com)&quot; as OCloud {
  rectangle &quot;云推理服务
专业版订阅 : 20€/mois&quot; as Cloud
  note right of Cloud
    C&#39;est le fournisseur d&#39;inférence.
    Mes modèles avec le tag :cloud
    sont exécutés sur LEURS serveurs.
    L&#39;abonnement Pro donne accès
    à des quotas supérieurs.
  end note
}

Dev --&amp;gt; CLI : &quot;我正在输入提示&quot;
CLI --&amp;gt; Client : &quot;调用此模型&quot;
Client --&amp;gt; Cloud : &quot;SSH 密钥 + 请求
(模型:cloud)&quot;
Client --&amp;gt; Client : &quot;本地执行
(不带 :cloud 的模型)&quot;

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock important&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-important&quot; title=&quot;❗&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;OpenCode 不是模型提供商。&lt;/strong&gt;这是一个开源的命令行界面(&lt;a href=&quot;https://github.com/anomalyco/opencode&quot;&gt;github.com/anomalyco/opencode&lt;/a&gt;) 它编排 AI 代理。它不销售订阅，也不提供推理。它相当于`git`用于版本控制：一个工具，而不是服务。 &lt;strong&gt;Ollama Cloud 是推理提供商。&lt;/strong&gt;我的本地 Ollama 安装就像 &lt;strong&gt;client&lt;/strong&gt; —— 它通过唯一的 SSH 密钥（Device Key）向 Ollama 服务器进行身份验证，并将带标签的模型的执行委托给它们。&lt;code&gt;:cloud&lt;/code&gt;. 专业版订阅（20欧元/月）解锁更高的配额，并允许通过 Docker 在同一台机器上累积多个账户。&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_介绍为什么要进行审计&quot;&gt;介绍：为什么要进行审计？&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;两个月前，我在本地 Ollama 安装上免费使用模型。然后我订阅了第一个 Ollama Cloud Pro 计划，每月 20 欧元，这使我能够使用云端模型（那些带有标签的`:cloud`)通过提供者`ollama-cloud`. 第二个订阅一个月后跟进，在一个独立的 Docker 实例上，使用其自身的帐户和 SSH 密钥 —  — 如 &lt;a href=&quot;0120_cumuler_deux_abonnements_ollama_pro_docker_post.html&quot;&gt;我的关于订阅叠加的文章&lt;/a&gt;中所述的叠加方法。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;困扰我的问题是：&lt;strong&gt;这每月20欧元是否合理？&lt;/strong&gt; 不是凭感觉。有数据说话。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;为了回答，我需要精确的数据。不是估计。不是平均。我的*实际*消耗，token 逐 token，模型 逐模型，会话 逐会话。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;和 OpenCode — CLI — 将所有内容存储在 SQLite 数据库中。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_opencode_数据库一座金矿&quot;&gt;OpenCode 数据库：一座金矿&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;OpenCode 将其会话的完整历史记录持久化到位于 的 SQLite 文件中`~/.local/share/opencode/opencode.db`. La mienne pèse 660 Mo pour 73 jours d&amp;#8217;utilisation — une base de données de production tout à fait respectable.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ ls -lh ~/.local/share/opencode/opencode.db
-rw-r--r-- 1 cheroliv cheroliv 660M mai 18 12:25 opencode.db&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_该图解&quot;&gt;该图解&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;该数据库包含大约二十张表，但其中有三张表对我们的审计至关重要：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontSize 12

title 简化模式 — OpenCode SQLite
entity &quot;会话&quot; as S {
  * id : TEXT
  --
  * model : TEXT (JSON)
  * cost : REAL
  * tokens_input : INTEGER
  * tokens_output : INTEGER
  * tokens_reasoning : INTEGER
  * tokens_cache_read : INTEGER
  * tokens_cache_write : INTEGER
  * time_created : INTEGER
  * project_id : TEXT
}

entity &quot;消息&quot; as M {
  * id : TEXT
  --
  * session_id : TEXT &amp;lt;&amp;lt;FK&amp;gt;&amp;gt;
  * data : TEXT (JSON)
  * time_created : INTEGER
}

entity &quot;项目&quot; as P {
  * id : TEXT
  --
  * worktree : TEXT
  * name : TEXT
}

S ||--o{ M : &quot;会话ID&quot;
S }o--|| P : &quot;项目ID&quot;

note right of S
  La table session agrège
  tokens + coût + modèle.
  C&#39;est notre point d&#39;entrée
  principal.
end note

note right of M
  Les messages individuels.
  Le champ data contient
  le modèle utilisé (format JSON)
  même si la session change
  de modèle en cours de route.
end note

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;桌子`session`非常适合全局审计：每个会话都有其累计的令牌计数、所使用的模型以及其成本。该字段`model`是原始 JSON :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-json hljs&quot; data-lang=&quot;json&quot;&gt;{
  &quot;id&quot;: &quot;deepseek-v4-pro:cloud&quot;,
  &quot;providerID&quot;: &quot;ollama-cloud&quot;,
  &quot;variant&quot;: &quot;default&quot;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock important&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-important&quot; title=&quot;❗&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;字段`cost`在 OpenCode 数据库中仅反映了 &lt;strong&gt;外部 API 费用&lt;/strong&gt;，即通过 API 密钥按使用量付费（Google Gemini、OpenAI 等）。通过 Ollama 的调用 — 无论是在本地还是通过 Ollama Cloud Pro — 都被标记`cost=0`因为费用是固定的（订阅），而不是按 token 计费。这些调用的真实成本就是每月订阅费。&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_提取代码&quot;&gt;提取代码&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;不需要安装任何东西。Node.js 22+ 集成了一个实验性的 SQLite 模块 (&lt;code&gt;node:sqlite&lt;/code&gt;) 运行完美。这是给我一切的脚本：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;const { DatabaseSync } = require(&#39;node:sqlite&#39;);
const db = new DatabaseSync(
  `${process.env.HOME}/.local/share/opencode/opencode.db`,
  { readonly: true }
);

// 1. Statistiques globales
const global = db.prepare(`
  SELECT
    COUNT(*) as sessions,
    SUM(tokens_input) as total_input,
    SUM(tokens_output) as total_output,
    SUM(tokens_reasoning) as total_reasoning,
    SUM(tokens_cache_read) as total_cache_read,
    SUM(cost) as total_cost
  FROM session
`).get();

// 2. Ventilation par modèle et fournisseur
const byModel = db.prepare(`
  SELECT
    json_extract(model, &#39;$.id&#39;) as model_id,
    json_extract(model, &#39;$.providerID&#39;) as provider,
    COUNT(*) as sessions,
    SUM(tokens_input) as total_input,
    SUM(tokens_output) as total_output,
    SUM(cost) as total_cost
  FROM session
  WHERE model IS NOT NULL
  GROUP BY model_id, provider
  ORDER BY SUM(tokens_input) DESC
`).all();

// 3. Par mois
const monthly = db.prepare(`
  SELECT
    strftime(&#39;%Y-%m&#39;, datetime(time_created/1000, &#39;unixepoch&#39;)) as month,
    COUNT(*) as sessions,
    SUM(tokens_input) as total_input,
    SUM(tokens_output) as total_output,
    SUM(cost) as total_cost
  FROM session
  WHERE time_created IS NOT NULL
  GROUP BY month
  ORDER BY month
`).all();

// 4. Messages par modèle (détection des changements intra-session)
const msgByModel = db.prepare(`
  SELECT
    json_extract(m.data, &#39;$.model.providerID&#39;) as provider,
    json_extract(m.data, &#39;$.model.modelID&#39;) as model_id,
    COUNT(*) as messages
  FROM message m
  WHERE json_extract(m.data, &#39;$.model&#39;) IS NOT NULL
  GROUP BY provider, model_id
  ORDER BY COUNT(*) DESC
`).all();

console.log({ global, byModel, monthly, msgByModel });
db.close();&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock note&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-note&quot; title=&quot;ℹ️&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;旗帜`--experimental-sqlite`在 Node.js 22.x 上是必需的。在 Node.js 24+ 上，模块是稳定的，不再需要标志。&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_结果73天消费&quot;&gt;结果：73天消费&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_全局视图&quot;&gt;全局视图&lt;/h3&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 33.3333%;&quot;&gt;
&lt;col style=&quot;width: 33.3333%;&quot;&gt;
&lt;col style=&quot;width: 33.3334%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;度量&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;价值&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;上下文&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;Sessions OpenCode&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;1 022&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;~14 次/天平均&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;标记输入&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;26.2亿&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;其中 94,5M 为缓存命中&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;Tokens Output&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;2100万&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;输入/输出比率 ~125:1&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;令牌推理&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;141 000&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;可忽略的 — 几乎没有思考&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;外部 API 成本&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;$0.22&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;非订阅费用 (Gemini + 免费层级)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;这个 \$0,22 的数字至关重要：它代表了我除了 Ollama Cloud Pro 订阅之外所支付的全部费用。换句话说，几乎可以忽略不计。订阅涵盖了主要内容。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontSize 12

title 每月演变 — 输入Tokens
rectangle &quot;2026年3月
9 次会话
37.7M 令牌&quot; as MARS #FFE082
rectangle &quot;2026年4月
486 个会话
1.33亿 tokens&quot; as AVR #81C784
rectangle &quot;2026年5月
527 次会话
1.25 亿个令牌&quot; as MAI #64B5F6

MARS -right-&amp;gt; AVR : ×35
AVR -right-&amp;gt; MAI : stable (période en cours)

note bottom of MAI
  Mai comptabilisé jusqu&#39;au 18.
  Projection mois complet : ~2,1 Md tokens
  si la tendance se maintient.
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;三月到四月的起飞十分壮观：一个月内增长了×35。这是从 « test » 使用过渡到 « production » 使用——也就是我开始为我的 Gradle 插件持续运行 OpenCode 代理的时候。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_按型号和供应商通风&quot;&gt;按型号和供应商通风&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;领域`model`的表格`session`是 JSON 的，`json_extract()`允许进行清洁通风：&lt;/p&gt;
&lt;/div&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 27.2727%;&quot;&gt;
&lt;col style=&quot;width: 18.1818%;&quot;&gt;
&lt;col style=&quot;width: 18.1818%;&quot;&gt;
&lt;col style=&quot;width: 18.1818%;&quot;&gt;
&lt;col style=&quot;width: 18.1819%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;模型 × 提供商&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;会话&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;输入&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;Output&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;成本&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;deepseek-v4-pro @ ollama-cloud&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;63&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;220 M&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;1,94 M&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;\$0&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;deepseek-v4-pro @ ollama-b&lt;/p&gt;&lt;/td&gt;
