&lt;li&gt;&lt;a href=&quot;#_配置排除&quot;&gt;配置排除&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_提取知识图谱&quot;&gt;提取知识图谱&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_步骤_2gradle_插件将知识图转换为_plantuml&quot;&gt;步骤 2：Gradle 插件将知识图转换为 PlantUML&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
