&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_介绍&quot;&gt;介�绍&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;静态网站的国际化（i18n）乍看起来可能很复杂，但JBake结合Thymeleaf提供了创建多语言站点的优雅解决方案。在本文中，我将展示我如何在我的博客上实现i18n，涵盖模板和多语言文章管理。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_用例图_use_case&quot;&gt;用例图 (Use Case)&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
left to right direction
skinparam packageStyle rectangle

actor &quot;作者&quot; as author
actor &quot;法语读者&quot; as reader_fr
actor &quot;英文阅读器&quot; as reader_en

rectangle &quot;JBake 多语言网站&quot; {
  usecase &quot;写文章 FR&quot; as UC1
  usecase &quot;写英文文章&quot; as UC2
  usecase &quot;配置国际化消息&quot; as UC3
  usecase &quot;生成站点&quot; as UC4
  usecase &quot;阅读FR文章&quot; as UC5
  usecase &quot;阅读英文文章&quot; as UC6
  usecase &quot;更改语言&quot; as UC7
  usecase &quot;查看可用翻译&quot; as UC8
}

author --&amp;gt; UC1
author --&amp;gt; UC2
author --&amp;gt; UC3
author --&amp;gt; UC4

reader_fr --&amp;gt; UC5
reader_fr --&amp;gt; UC7
reader_fr --&amp;gt; UC8

reader_en --&amp;gt; UC6
reader_en --&amp;gt; UC7
reader_en --&amp;gt; UC8

UC1 ..&amp;gt; UC4 : &amp;lt;&amp;lt;include&amp;gt;&amp;gt;
UC2 ..&amp;gt; UC4 : &amp;lt;&amp;lt;include&amp;gt;&amp;gt;
UC3 ..&amp;gt; UC4 : &amp;lt;&amp;lt;include&amp;gt;&amp;gt;
UC5 ..&amp;gt; UC8 : &amp;lt;&amp;lt;extend&amp;gt;&amp;gt;
UC6 ..&amp;gt; UC8 : &amp;lt;&amp;lt;extend&amp;gt;&amp;gt;
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_国际化架构&quot;&gt;国际化架构&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;我们的方法基于两个支柱：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;模板的国际化&lt;/strong&gt;: 使用 Thymeleaf 消息文件用于界面元素&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;内容的 i18n&lt;/strong&gt;按语言组织文章，放置在专用的文件夹结构中&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_结构图文件组织&quot;&gt;结构图（文件组织）&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
@startsalt
{
{T
+ projet-jbake
++ content
+++ blog
++++ 2024
+++++ fr
++++++ article1.adoc
++++++ article2.adoc
+++++ en
++++++ article1.adoc
++++++ article2.adoc
++++ 2025
+++++ fr
++++++ guide-i18n.adoc
+++++ en
++++++ i18n-guide.adoc
++ templates
+++ post.html
+++ index.html
+++ index_en.html
+++ messages.properties
+++ messages_fr.properties
+++ messages_en.properties
++ assets
+++ css
+++ js
+++ img
++ jbake.properties
++ output
+++ fr
++++ blog
+++++ 2025
++++++ guide-i18n.html
+++ en
++++ blog
+++++ 2025
++++++ i18n-guide.html
}
}
@endsalt
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_为什么采用这种方法&quot;&gt;为什么采用这种方法？&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;这种分离可以：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;保持界面一致性，无论语言如何&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;独立管理文章的内容和翻译&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;简化添加新语言，无需进行大规模重构&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;允许仅在特定语言中可用的文章&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_组件图&quot;&gt;组件图&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam componentStyle rectangle

package &quot;来源&quot; {
  folder &quot;content/blog/2025/&quot; {
    folder &quot;fr/&quot; as content_fr {
      [article1.adoc]
      [article2.adoc]
    }
    folder &quot;的/&quot; as content_en {
      [article1.adoc] as article1_en
      [article2.adoc] as article2_en
    }
  }

  folder &quot;模板/&quot; {
    [post.html]
    [index.html]
    [index_en.html]
  }

  folder &quot;消息/&quot; {
    [messages_fr.properties]
    [messages_en.properties]
  }

  [jbake.properties]
}

package &quot;JBake 引擎&quot; {
  [Parser AsciiDoc] as parser
  [Template Engine\nThymeleaf] as thymeleaf
  [Generator] as generator
  [I18n Resolver] as i18n
}

package &quot;已生成的网站&quot; {
  folder &quot;fr/&quot; {
    folder &quot;blog/2025/&quot; as blog_fr {
      [article1.html]
      [article2.html]
    }
  }

  folder &quot;的/&quot; {
    folder &quot;blog/2025/&quot; as blog_en {
      [article1.html] as article1_html_en
      [article2.html] as article2_html_en
    }
  }
}

content_fr --&amp;gt; parser
content_en --&amp;gt; parser
parser --&amp;gt; generator

templates --&amp;gt; thymeleaf
messages --&amp;gt; i18n
i18n --&amp;gt; thymeleaf
thymeleaf --&amp;gt; generator
jbake.properties --&amp;gt; generator

generator --&amp;gt; blog_fr
generator --&amp;gt; blog_en
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_thymeleaf_模板国际化&quot;&gt;Thymeleaf 模板国际化&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_消息文件的结构&quot;&gt;消息文件的结构&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;第一步是为每种支持的语言创建属性文件：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;src/jbake/templates/
├── messages.properties        # Fallback par défaut
├── messages_fr.properties     # Français
├── messages_en.properties     # Anglais
└── messages_de.properties     # Allemand&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_消息文件的内容&quot;&gt;消息文件的内容&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;这是一个文件示例`messages_fr.properties`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Navigation
nav.home=Accueil
nav.blog=Blog
nav.about=À propos
nav.contact=Contact

# Articles
article.readmore=Lire la suite
article.published=Publié le
article.tags=Étiquettes
article.also.available=Également disponible en

# Interface
site.title=Mon Blog Technique
site.description=Partage de connaissances et expériences
footer.copyright=© 2025 Tous droits réservés
search.placeholder=Rechercher un article...&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;以及其英语等价`messages_en.properties`：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Navigation
nav.home=Home
nav.blog=Blog
nav.about=About
nav.contact=Contact

# Articles
article.readmore=Read more
article.published=Published on
article.tags=Tags
article.also.available=Also available in

# Interface
site.title=My Tech Blog
site.description=Sharing knowledge and experiences
footer.copyright=© 2025 All rights reserved
search.placeholder=Search articles...&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_在模板中使用&quot;&gt;在模板中使用&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;在您的Thymeleaf模板中，使用语法`#{}`要访问消息 :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;Mon Blog&amp;lt;/title&amp;gt;
    &amp;lt;meta name=&quot;description&quot; th:content=&quot;#{site.description}&quot; /&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;nav&amp;gt;
        &amp;lt;a th:href=&quot;@{/}&quot; th:text=&quot;#{nav.home}&quot;&amp;gt;Accueil&amp;lt;/a&amp;gt;
        &amp;lt;a th:href=&quot;@{/blog/}&quot; th:text=&quot;#{nav.blog}&quot;&amp;gt;Blog&amp;lt;/a&amp;gt;
        &amp;lt;a th:href=&quot;@{/about.html}&quot; th:text=&quot;#{nav.about}&quot;&amp;gt;À propos&amp;lt;/a&amp;gt;
    &amp;lt;/nav&amp;gt;

    &amp;lt;footer&amp;gt;
        &amp;lt;p th:text=&quot;#{footer.copyright}&quot;&amp;gt;Copyright&amp;lt;/p&amp;gt;
    &amp;lt;/footer&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_时序图_国际化解决方案&quot;&gt;时序图 - 国际化解决方案&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
actor Auteur
participant JBake
participant &quot;AsciiDoc
解析器&quot; as parser
participant &quot;Thymeleaf\n引擎&quot; as thymeleaf
participant &quot;I18n
解析器&quot; as i18n
database &quot;messages_*.properties&quot; as messages

Auteur -&amp;gt; JBake: jbake -b
activate JBake

JBake -&amp;gt; parser: Lire article.fr.adoc
activate parser
parser --&amp;gt; JBake: Contenu + métadonnées\n(lang=fr, article-id=xyz)
deactivate parser

JBake -&amp;gt; parser: Lire article.en.adoc
activate parser
parser --&amp;gt; JBake: Contenu + métadonnées\n(lang=en, article-id=xyz)
deactivate parser

JBake -&amp;gt; thymeleaf: Générer page FR
activate thymeleaf

thymeleaf -&amp;gt; i18n: Résoudre #{nav.home}
activate i18n
i18n -&amp;gt; messages: Lire messages_fr.properties
messages --&amp;gt; i18n: &quot;首页&quot;
i18n --&amp;gt; thymeleaf: &quot;首页&quot;
deactivate i18n

thymeleaf -&amp;gt; JBake: Rechercher traductions\n(article-id=xyz, lang!=fr)
JBake --&amp;gt; thymeleaf: article.en.html trouvé

thymeleaf --&amp;gt; JBake: /fr/blog/article.html
deactivate thymeleaf

JBake -&amp;gt; thymeleaf: Générer page EN
activate thymeleaf

thymeleaf -&amp;gt; i18n: Résoudre #{nav.home}
activate i18n
i18n -&amp;gt; messages: Lire messages_en.properties
messages --&amp;gt; i18n: &quot;首页&quot;
i18n --&amp;gt; thymeleaf: &quot;首页&quot;
deactivate i18n

thymeleaf -&amp;gt; JBake: Rechercher traductions\n(article-id=xyz, lang!=en)
JBake --&amp;gt; thymeleaf: article.fr.html trouvé

thymeleaf --&amp;gt; JBake: /en/blog/article.html
deactivate thymeleaf

JBake --&amp;gt; Auteur: Site généré
deactivate JBake
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_jbake_的语言环境配置&quot;&gt;JBake 的语言环境配置&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;在您的文件中`jbake.properties`, 设置默认语言环境 :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Locale par défaut
thymeleaf.locale=fr

# Encodage
template.encoding=UTF-8&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_文章国际化按文件夹组织&quot;&gt;文章国际化：按文件夹组织&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_流程图_flow_生成&quot;&gt;流程图 (Flow) - 生成&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start

:Lire jbake.properties;
:Charger configuration i18n;

partition &quot;对于每个 AsciiDoc 文件&quot; {
  :Lire métadonnées\n(:jbake-lang:, :jbake-article-id:);
  :Parser contenu AsciiDoc;
  :Stocker en mémoire avec langue;
}

partition &quot;对于每个模板&quot; {
  :Charger template Thymeleaf;
  :Identifier langue cible;
  :Charger messages_{lang}.properties;

  partition &quot;内容过滤&quot; {
    :Filtrer articles par langue;
    :Grouper traductions\npar article-id;
  }

  :Appliquer template avec i18n;
  :Générer HTML dans /{lang}/;
}

:Copier assets statiques;
:Générer sitemap multilingue;
:Générer flux RSS par langue;

stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_文件夹结构&quot;&gt;文件夹结构&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;与其在文件名中使用后缀，我选择了按文件夹组织的方式，这样更清晰且易于维护：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;content/blog/
├── 2024/
│   ├── fr/
│   │   ├── introduction-jbake.adoc
│   │   ├── guide-thymeleaf.adoc
│   │   └── astuces-asciidoc.adoc
│   └── en/
│       ├── introduction-jbake.adoc
│       ├── thymeleaf-guide.adoc
│       └── asciidoc-tips.adoc
└── 2025/
    ├── fr/
    │   └── internationalisation-jbake.adoc
    └── en/
        └── jbake-internationalization.adoc&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_这种方法的优势&quot;&gt;这种方法的优势&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;这种结构具有多个优势：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;清晰的分离&lt;/strong&gt;: 每种语言都有自己的空间&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;灵活命名&lt;/strong&gt;: 文件可以根据语言具有不同的名称&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;可扩展性&lt;/strong&gt;: 容易添加一种新语言&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;自然组织&lt;/strong&gt;: 遵循 JBake 的时间逻辑&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_文章的元数据&quot;&gt;文章的元数据&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;每篇文章都必须包含元数据以允许翻译之间的链接。以下是一个示例：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;法文版&lt;/strong&gt;(&lt;code&gt;2025/fr/internationalisation-jbake.adoc&lt;/code&gt;) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;= Internationalisation d&#39;un site statique JBake
:jbake-type: post
:jbake-status: published
:jbake-date: 2025-10-20
:jbake-lang: fr
:jbake-article-id: jbake-i18n-thymeleaf
:jbake-tags: jbake, thymeleaf, i18n
:jbake-description: Guide pour mettre en place l&#39;i18n avec JBake&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;英文版本&lt;/strong&gt;(&lt;code&gt;2025/en/jbake-internationalization.adoc&lt;/code&gt;) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;= Internationalizing a JBake Static Site
:jbake-type: post
:jbake-status: published
:jbake-date: 2025-10-20
:jbake-lang: en
:jbake-article-id: jbake-i18n-thymeleaf
:jbake-tags: jbake, thymeleaf, i18n
:jbake-description: Guide to implement i18n with JBake&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;注意：该属性`:jbake-article-id:`至关重要：它能够将同一篇文章的不同译文关联起来。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_url_配置&quot;&gt;URL 配置&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;在`jbake.properties`, 配置 URL 模式以包含语言 :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Pattern d&#39;URL avec langue
post.permalink.pattern=:lang/blog/:year/:name.html

# Langue par défaut
site.default.lang=fr&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;这将生成如下形式的 URL：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;/fr/blog/2025/internationalisation-jbake.html&lt;/code&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;/en/blog/2025/jbake-internationalization.html&lt;/code&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_多语言显示模板&quot;&gt;多语言显示模板&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_带有语言选择器的文章模板&quot;&gt;带有语言选择器的文章模板&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;创建一个模板`post.html`显示可用翻译：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;${content.title}&quot;&amp;gt;Article&amp;lt;/title&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;article&amp;gt;
        &amp;lt;header&amp;gt;
            &amp;lt;h1 th:text=&quot;${content.title}&quot;&amp;gt;Titre&amp;lt;/h1&amp;gt;

            &amp;lt;div class=&quot;article-meta&quot;&amp;gt;
                &amp;lt;time th:text=&quot;${#dates.format(content.date, &#39;dd MMMM yyyy&#39;)}&quot;
                      th:attr=&quot;datetime=${#dates.format(content.date, &#39;yyyy-MM-dd&#39;)}&quot;&amp;gt;
                    Date
                &amp;lt;/time&amp;gt;

                &amp;lt;!-- Sélecteur de traductions --&amp;gt;
                &amp;lt;div class=&quot;translations&quot; th:if=&quot;${content[&#39;article-id&#39;]}&quot;&amp;gt;
                    &amp;lt;span th:text=&quot;#{article.also.available}&quot;&amp;gt;Aussi disponible en :&amp;lt;/span&amp;gt;
                    &amp;lt;ul class=&quot;language-list&quot;&amp;gt;
                        &amp;lt;li th:each=&quot;post : ${published_posts}&quot;
                            th:if=&quot;${post[&#39;article-id&#39;] == content[&#39;article-id&#39;] and post.lang != content.lang}&quot;&amp;gt;
                            &amp;lt;a th:href=&quot;${post.uri}&quot;
                               th:text=&quot;${post.lang.toUpperCase()}&quot;&amp;gt;
                                LANG
                            &amp;lt;/a&amp;gt;
                        &amp;lt;/li&amp;gt;
                    &amp;lt;/ul&amp;gt;
                &amp;lt;/div&amp;gt;
            &amp;lt;/div&amp;gt;
        &amp;lt;/header&amp;gt;

        &amp;lt;div class=&quot;content&quot; th:utext=&quot;${content.body}&quot;&amp;gt;
            Contenu de l&#39;article
        &amp;lt;/div&amp;gt;

        &amp;lt;footer class=&quot;article-footer&quot;&amp;gt;
            &amp;lt;div class=&quot;tags&quot; th:if=&quot;${content.tags}&quot;&amp;gt;
                &amp;lt;span th:text=&quot;#{article.tags}&quot;&amp;gt;Étiquettes :&amp;lt;/span&amp;gt;
                &amp;lt;span th:each=&quot;tag : ${content.tags}&quot;&amp;gt;
                    &amp;lt;a th:href=&quot;@{/tags/{tag}.html(tag=${tag})}&quot;
                       th:text=&quot;${tag}&quot;&amp;gt;tag&amp;lt;/a&amp;gt;
                &amp;lt;/span&amp;gt;
            &amp;lt;/div&amp;gt;
        &amp;lt;/footer&amp;gt;
    &amp;lt;/article&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_按语言过滤的索引&quot;&gt;按语言过滤的索引&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;为每种语言创建索引模板：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;index.html&lt;/strong&gt;(法文索引) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;Mon Blog&amp;lt;/title&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;main&amp;gt;
        &amp;lt;h1 th:text=&quot;#{nav.blog}&quot;&amp;gt;Blog&amp;lt;/h1&amp;gt;

        &amp;lt;div class=&quot;articles-list&quot;&amp;gt;
            &amp;lt;article th:each=&quot;post : ${published_posts}&quot;
                     th:if=&quot;${post.lang == &#39;fr&#39;}&quot;&amp;gt;
                &amp;lt;h2&amp;gt;
                    &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;${post.title}&quot;&amp;gt;Titre&amp;lt;/a&amp;gt;
                &amp;lt;/h2&amp;gt;
                &amp;lt;time th:text=&quot;${#dates.format(post.date, &#39;dd MMMM yyyy&#39;)}&quot;&amp;gt;
                    Date
                &amp;lt;/time&amp;gt;
                &amp;lt;p th:text=&quot;${post.description}&quot;&amp;gt;Description&amp;lt;/p&amp;gt;
                &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;#{article.readmore}&quot;&amp;gt;
                    Lire la suite
                &amp;lt;/a&amp;gt;
            &amp;lt;/article&amp;gt;
        &amp;lt;/div&amp;gt;
    &amp;lt;/main&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;index_en.html&lt;/strong&gt;(英文索引) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;My Blog&amp;lt;/title&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;main&amp;gt;
        &amp;lt;h1 th:text=&quot;#{nav.blog}&quot;&amp;gt;Blog&amp;lt;/h1&amp;gt;

        &amp;lt;div class=&quot;articles-list&quot;&amp;gt;
            &amp;lt;article th:each=&quot;post : ${published_posts}&quot;
                     th:if=&quot;${post.lang == &#39;en&#39;}&quot;&amp;gt;
                &amp;lt;h2&amp;gt;
                    &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;${post.title}&quot;&amp;gt;Title&amp;lt;/a&amp;gt;
                &amp;lt;/h2&amp;gt;
                &amp;lt;time th:text=&quot;${#dates.format(post.date, &#39;dd MMMM yyyy&#39;)}&quot;&amp;gt;
                    Date
                &amp;lt;/time&amp;gt;
                &amp;lt;p th:text=&quot;${post.description}&quot;&amp;gt;Description&amp;lt;/p&amp;gt;
                &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;#{article.readmore}&quot;&amp;gt;
                    Read more
                &amp;lt;/a&amp;gt;
            &amp;lt;/article&amp;gt;
        &amp;lt;/div&amp;gt;
    &amp;lt;/main&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_语言之间的导航&quot;&gt;语言之间的导航&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_全局语言选择器&quot;&gt;全局语言选择器&lt;/h3&gt;

&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_流程图_用户读取&quot;&gt;流程图 - 用户读取&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start

:Utilisateur accède au site;

if (Langue préférée ?) then (FR)
  :Afficher /index.html;
  :Lister articles FR;
else (EN)
  :Afficher /en/index.html;
  :Lister articles EN;
endif

:Utilisateur clique sur article;

:Afficher article\navec métadonnées;

if (Traductions disponibles ?) then (oui)
  :Afficher sélecteur\nde traductions;

  if (Changement de langue ?) then (oui)
    :Rediriger vers\ntraduction;
    :Afficher article\ndans nouvelle langue;
  else (non)
    :Continuer lecture;
  endif
else (non)
  :Continuer lecture;
endif

stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;在你的主模板中添加语言选择器：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;nav class=&quot;language-switcher&quot;&amp;gt;
    &amp;lt;a href=&quot;/index.html&quot;
       th:classappend=&quot;${content.lang == &#39;fr&#39;} ? &#39;active&#39;&quot;
       title=&quot;Français&quot;&amp;gt;
        🇫🇷 FR
    &amp;lt;/a&amp;gt;
    &amp;lt;a href=&quot;/en/index.html&quot;
       th:classappend=&quot;${content.lang == &#39;en&#39;} ? &#39;active&#39;&quot;
       title=&quot;English&quot;&amp;gt;
        🇬🇧 EN
    &amp;lt;/a&amp;gt;
&amp;lt;/nav&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_选择器的_css_样式&quot;&gt;选择器的 CSS 样式&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-css hljs&quot; data-lang=&quot;css&quot;&gt;.language-switcher {
    display: flex;
    gap: 1rem;
    padding: 0.5rem;
    background: #f5f5f5;
    border-radius: 4px;
}

.language-switcher a {
    padding: 0.5rem 1rem;
    text-decoration: none;
    color: #333;
    border-radius: 4px;
    transition: background 0.2s;
}

.language-switcher a:hover {
    background: #e0e0e0;
}

.language-switcher a.active {
    background: #007bff;
    color: white;
}

.translations {
    margin: 1rem 0;
    padding: 1rem;
    background: #f8f9fa;
    border-left: 4px solid #007bff;
}

.language-list {
    display: inline-flex;
    gap: 0.5rem;
    list-style: none;
    padding: 0;
    margin: 0;
}

.language-list li::after {
    content: &quot;•&quot;;
    margin-left: 0.5rem;
}

.language-list li:last-child::after {
    content: &quot;&quot;;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_按语言的_rss_订阅&quot;&gt;按语言的 RSS 订阅&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;要获得按语言分离的 RSS 源，请创建单独的模板：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;feed.xml&lt;/strong&gt;(法语流) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-xml hljs&quot; data-lang=&quot;xml&quot;&gt;&amp;lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&amp;gt;
&amp;lt;rss version=&quot;2.0&quot; xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
    &amp;lt;channel&amp;gt;
        &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;Mon Blog&amp;lt;/title&amp;gt;
        &amp;lt;link th:text=&quot;${config.site_host}&quot;&amp;gt;http://example.com&amp;lt;/link&amp;gt;
        &amp;lt;description th:text=&quot;#{site.description}&quot;&amp;gt;Description&amp;lt;/description&amp;gt;
        &amp;lt;language&amp;gt;fr&amp;lt;/language&amp;gt;

        &amp;lt;item th:each=&quot;post : ${published_posts}&quot;
              th:if=&quot;${post.lang == &#39;fr&#39;}&quot;&amp;gt;
            &amp;lt;title th:text=&quot;${post.title}&quot;&amp;gt;Titre&amp;lt;/title&amp;gt;
            &amp;lt;link th:text=&quot;${config.site_host + post.uri}&quot;&amp;gt;Lien&amp;lt;/link&amp;gt;
            &amp;lt;pubDate th:text=&quot;${#dates.format(post.date, &#39;EEE, dd MMM yyyy HH:mm:ss Z&#39;)}&quot;&amp;gt;
                Date
            &amp;lt;/pubDate&amp;gt;
            &amp;lt;description th:text=&quot;${post.description}&quot;&amp;gt;Description&amp;lt;/description&amp;gt;
        &amp;lt;/item&amp;gt;
    &amp;lt;/channel&amp;gt;
&amp;lt;/rss&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_良好实践和技巧&quot;&gt;良好实践和技巧&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_1_文章标识符的一致性&quot;&gt;1. 文章标识符的一致性&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;请确保`:jbake-article-id:`对于同一文章的所有翻译都是相同的。 请使用一致的格式：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;请使用英文标识符以实现通用性&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;使用短横线来分隔单词&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;避免使用特殊字符&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_日期一致&quot;&gt;2. 日期一致&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;一篇文章的所有翻译必须有相同的出版日期`:jbake-date:`). 这有助于排序和按时间顺序显示。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_3_多语言标签&quot;&gt;3. 多语言标签&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;对于标签，您有两种选择：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;选项1：通用英文标签&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;:jbake-tags: java, spring-boot, microservices&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;选项 2：使用映射翻译的标签&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;# Version française
:jbake-tags: java, spring-boot, microservices

# Version anglaise
:jbake-tags: java, spring-boot, microservices&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_未翻译项目的管理&quot;&gt;4. 未翻译项目的管理&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;不需要翻译所有文章。如果某篇文章只存在于一种语言中，它将不会出现在另一种语言的列表中。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_5_多语言站点地图&quot;&gt;5. 多语言站点地图&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;生成一个包含所有语言的站点地图：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-xml hljs&quot; data-lang=&quot;xml&quot;&gt;&amp;lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&amp;gt;
&amp;lt;urlset xmlns=&quot;http://www.sitemaps.org/schemas/sitemap/0.9&quot;
        xmlns:xhtml=&quot;http://www.w3.org/1999/xhtml&quot;
        xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
    &amp;lt;url th:each=&quot;post : ${published_posts}&quot;&amp;gt;
        &amp;lt;loc th:text=&quot;${config.site_host + post.uri}&quot;&amp;gt;URL&amp;lt;/loc&amp;gt;
        &amp;lt;lastmod th:text=&quot;${#dates.format(post.date, &#39;yyyy-MM-dd&#39;)}&quot;&amp;gt;Date&amp;lt;/lastmod&amp;gt;

        &amp;lt;!-- Liens alternatifs pour les traductions --&amp;gt;
        &amp;lt;xhtml:link th:each=&quot;translation : ${published_posts}&quot;
                    th:if=&quot;${translation[&#39;article-id&#39;] == post[&#39;article-id&#39;] and translation.lang != post.lang}&quot;
                    rel=&quot;alternate&quot;
                    th:attr=&quot;hreflang=${translation.lang},href=${config.site_host + translation.uri}&quot; /&amp;gt;
    &amp;lt;/url&amp;gt;
&amp;lt;/urlset&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_结论&quot;&gt;结论&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;使用 Thymeleaf 对 JBake 站点进行国际化是一种健壮且可维护的方法。通过将 i18n 与模板分离（通过消息文件）以及将内容的 i18n 通过目录组织来分离，您可以获得一个灵活、易于演进的系统。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;要点如下：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Thymeleaf 消息文件&lt;/strong&gt;对于用户界面&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;按文件夹组织&lt;/strong&gt;(年/语言) 用于文章&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;文章标识符&lt;/strong&gt;用于链接翻译&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;专用模板&lt;/strong&gt;对于每种语言&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;显式 URL&lt;/strong&gt;包含语言代码&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_部署图&quot;&gt;部署图&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
node &quot;开发机器&quot; {
  artifact &quot;来源&quot; {
    folder &quot;content/&quot;
    folder &quot;模板/&quot;
    folder &quot;资产/&quot;
  }

  component &quot;JBake 命令行界面&quot; as jbake

  Sources --&amp;gt; jbake : jbake -b
}

node &quot;构建服务器\n(CI/CD)&quot; {
  component &quot;GitHub Actions
或 GitLab CI&quot; as ci

  jbake --&amp;gt; ci : push
}

cloud &quot;CDN / 托管&quot; {
  node &quot;静态Web服务器&quot; {
    artifact &quot;已生成的网站&quot; {
      folder &quot;/fr/blog/&quot;
      folder &quot;/en/blog/&quot;
      folder &quot;/assets/&quot;
    }
  }
}

ci --&amp;gt; &quot;已生成的网站&quot; : déploiement

actor &quot;读者&quot; as users

users --&amp;gt; &quot;静态Web服务器&quot; : HTTPS
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;这种架构让您可以简单地使用两种语言开始，并且可以在不进行大规模重构的情况下添加更多语言。整个系统保持完全静态且高性能，忠实于JBake的理念。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;祝您多语言开发顺利！🌍&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table of Contents&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_简介&quot;&gt;简介&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_下载_tor_及其签名&quot;&gt;下载 Tor 及其签名&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_签名的加密验证&quot;&gt;签名的加密验证&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_导入_tor_项目的公钥&quot;&gt;导入 Tor 项目的公钥&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_检查签名&quot;&gt;2. 检查签名&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_实践案例签名有效但密钥未认证&quot;&gt;实践案例：签名有效但密钥未认证&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_为什么要验证签名&quot;&gt;为什么要验证签名？&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_提取和启动_tor_browser&quot;&gt;提取和启动 Tor Browser&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_集成到ubuntu桌面&quot;&gt;集成到Ubuntu桌面&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_使用tor探索教育资源&quot;&gt;使用Tor探索教育资源&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_tor_浏览器更新&quot;&gt;Tor 浏览器更新&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_结论&quot;&gt;结论&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_参考文献&quot;&gt;参考文献&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_简介&quot;&gt;简介&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;在一个数字隐私日益受到威胁的世界里，&lt;strong&gt;Tor Browser&lt;/strong&gt; 仍然是保护匿名和信息自由的重要工具。 然而，执行下载的软件而不先有 是至关重要的&lt;strong&gt;验证了其真实性&lt;/strong&gt;。 本文介绍了一种完整的方法：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;下载 &lt;strong&gt;Tor Browser&lt;/strong&gt; 及其签名`.asc`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;验证下载文件的有效性&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;在 Ubuntu 上安装并启动 &lt;strong&gt;Tor Browser&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;将其添加到桌面菜单以供日常使用&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;通过 Tor 探索教育资源和道德的 OSINT&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_下载_tor_及其签名&quot;&gt;下载 Tor 及其签名&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;为Tor浏览器创建一个专用文件夹：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;mkdir -p ~/workspace/tipiak/tor
cd ~/workspace/tipiak/tor&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;然后下载Tor浏览器的归档文件及其签名：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;wget https://www.torproject.org/dist/torbrowser/14.5.7/tor-browser-linux-x86_64-14.5.7.tar.xz
wget https://www.torproject.org/dist/torbrowser/14.5.7/tor-browser-linux-x86_64-14.5.7.tar.xz.asc&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_签名的加密验证&quot;&gt;签名的加密验证&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;此步骤是&lt;strong&gt;必不可少的&lt;/strong&gt;为了确保下载的文件确实来自 &lt;strong&gt;Tor Project&lt;/strong&gt; 并且未被修改。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_导入_tor_项目的公钥&quot;&gt;导入 Tor 项目的公钥&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gpg --auto-key-locate nodefault,wkd --locate-keys torbrowser@torproject.org&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;�检查密钥是否已正确导入：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gpg --list-keys torbrowser@torproject.org&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_检查签名&quot;&gt;2. 检查签名&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gpg --verify tor-browser-linux-x86_64-14.5.7.tar.xz.asc tor-browser-linux-x86_64-14.5.7.tar.xz&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;如果一切正确，将显示以下消息：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-none hljs&quot;&gt;gpg: Good signature from &quot;Tor Browser Developers (signing key)&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;如果出现未认证密钥警告，这仅仅意味着您尚未签署 Tor 项目的可信密钥，但该签名仍然有效。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_实践案例签名有效但密钥未认证&quot;&gt;实践案例：签名有效但密钥未认证&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;在验证过程中，经常会遇到这样的消息：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-none hljs&quot;&gt;gpg --verify tor-browser-linux-x86_64-14.5.7.tar.xz.asc tor-browser-linux-x86_64-14.5.7.tar.xz
gpg: Signature faite le mar. 16 sept. 2025 14:26:26 CEST
gpg:                avec la clef RSA CAAE408AEBE2288E96FC5D5E157432CF78A65729
gpg: Bonne signature de « Tor Browser Developers (signing key) &amp;lt;torbrowser@torproject.org&amp;gt; » [inconnu]
gpg: Attention : cette clef n&#39;est pas certifiée avec une signature de confiance.
gpg:          Rien n&#39;indique que la signature appartient à son propriétaire.
Empreinte de clef principale : EF6E 286D DA85 EA2A 4BA7  DE68 4E2C 6E87 9329 8290
     Empreinte de la sous-clef : CAAE 408A EBE2 288E 96FC  5D5E 1574 32CF 78A6 5729&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;此消息表明签名在技术上是“有效的”（文件未被修改），但您的 GPG 系统无法 &lt;strong&gt;验证对该密钥本身的信任&lt;/strong&gt;。为了消除此疑虑，必须比较主密钥的指纹 (&lt;code&gt;EF6E 286D DA85 EA2A 4BA7 DE68 4E2C 6E87 9329 8290&lt;/code&gt;) 与Tor Project官方网站上发布的内容相同。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;根据官方网站，预期的指纹是：&lt;code&gt;EF6E286DDA85EA2A4BA7DE684E2C6E8793298290&lt;/code&gt;。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;由于显示的印记由`gpg`如果它*完全*对应于官方网站的那个，您可以确定密钥是合法的且文件是安全的。‘未认证密钥’的警告则是关于您本地 GPG 配置的信息，而非关于签名的有效性或文件的真实性。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_为什么要验证签名&quot;&gt;为什么要验证签名？&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;验证 GPG 签名是数字安全的基本行为。 它可以：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;保证&lt;strong&gt;真实性&lt;/strong&gt;已下载的软件&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;防止受恶意行为者破坏的文件被安装&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;参加&lt;strong&gt;数字主权&lt;/strong&gt;个体的&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;�促进负责任且符合伦理的数字文化&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
left to right direction
actor &quot;用户&quot; as U
actor &quot;TorProject 服务器&quot; as S

usecase &quot;下载 Tor 及其签名&quot; as D
usecase &quot;导入公钥&quot; as K
usecase &quot;验证 GPG 签名&quot; as V
usecase &quot;安装并启动 Tor&quot; as I

U --&amp;gt; D
U --&amp;gt; K
U --&amp;gt; V
U --&amp;gt; I
S --&amp;gt; D

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_提取和启动_tor_browser&quot;&gt;提取和启动 Tor Browser&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;解压已下载的压缩包：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;tar -xvf tor-browser-linux-x86_64-14.5.7.tar.xz
cd tor-browser&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;然后启动浏览器：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./start-tor-browser.desktop&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;首次启动时，将打开一个配置窗口以建立与Tor网络的连接。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_集成到ubuntu桌面&quot;&gt;集成到Ubuntu桌面&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;要将 &lt;strong&gt;Tor Browser&lt;/strong&gt; 添加到应用程序菜单：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./start-tor-browser.desktop --register-app&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;您 可以 然后 :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;从应用程序菜单启动 &lt;strong&gt;Tor Browser&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;将其添加到 Dock 收藏夹&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;如需，创建快捷键&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start
:Téléchargement de Tor;
:Importation de la clé GPG;
:Vérification de la signature;
if (Signature valide ?) then (Oui)
:Extraction du navigateur;
:Lancement du navigateur Tor;
:Enregistrement dans le bureau;
else (Non)
:Supprimer le fichier compromis;
endif
stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_使用tor探索教育资源&quot;&gt;使用Tor探索教育资源&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Tor 不仅仅是一个匿名工具。 它是一个通往教育和科研资源的门户，尤其在以下领域：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;开源情报（Open Source Intelligence）&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://inteltechniques.com&quot;&gt;https://inteltechniques.com&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://osintframework.com&quot;&gt;https://osintframework.com&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;教育共享和开源&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://archive.org&quot;&gt;https://archive.org&lt;/a&gt;(通过 Tor 访问以获得更高的隐私)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://github.com/&quot;&gt;https://github.com/&lt;/a&gt;(可通过 Tor 访问)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://librarygenesis.pro&quot;&gt;https://librarygenesis.pro&lt;/a&gt;(开放获取科学文献)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;知识的传播与对数字社会中人类的理解&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;关于数字文化、言论自由和获取知识的资源&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;自由的网络安全和技术伦理文档&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_tor_浏览器更新&quot;&gt;Tor 浏览器更新&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;为了确保最佳安全性，保持 &lt;strong&gt;Tor Browser&lt;/strong&gt; 更新至关重要。浏览器内置了一个可以通过命令行触发的自动更新机制。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;从 Tor Browser 安装目录，只需重新启动启动脚本：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;cd ~/workspace/tipiak/tor/tor-browser
./start-tor-browser.desktop&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;启动时，&lt;strong&gt;Tor Browser&lt;/strong&gt; 会自动检查是否有新版本。如果有，它会为您下载并安装。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;这种简单的方法可确保您始终拥有最新的安全补丁和最新的改进，这对于安全浏览至关重要。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_结论&quot;&gt;结论&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;检查自己的下载是所有希望在安全数字环境中前进的人必不可少的习惯。 以验证的方式安装 Tor，这是&lt;strong&gt;保护其数字完整性&lt;/strong&gt;, &lt;strong&gt;保持对自由软件的信任&lt;/strong&gt;, et &lt;strong&gt;加强其信息自主性&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;数字安全是良知的行为，而非偏执。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
title Tor使用概览
actor Utilisateur
rectangle &quot;Tor 浏览器&quot; {
rectangle &quot;匿名&quot; as A
rectangle &quot;OSINT调查&quot; as O
rectangle &quot;教育分享&quot; as E
}
Utilisateur --&amp;gt; A
Utilisateur --&amp;gt; O
Utilisateur --&amp;gt; E
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_参考文献&quot;&gt;参考文献&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Tor 项目官方网站 :https://www.torproject.org/download/[&lt;a href=&quot;https://www.torproject.org/download/&quot; class=&quot;bare&quot;&gt;https://www.torproject.org/download/&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;签名验证文档：https://support.torproject.org/tbb/how-to-verify-signature/[&lt;a href=&quot;https://support.torproject.org/tbb/how-to-verify-signature/&quot; class=&quot;bare&quot;&gt;https://support.torproject.org/tbb/how-to-verify-signature/&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Ubuntu 文档：https://ubuntu.com[&lt;a href=&quot;https://ubuntu.com&quot; class=&quot;bare&quot;&gt;https://ubuntu.com&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;教育档案：https://archive.org/details/opensource[&lt;a href=&quot;https://archive.org/details/opensource&quot; class=&quot;bare&quot;&gt;https://archive.org/details/opensource&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock note&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-note&quot; title=&quot;Note&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;本文属于 &lt;strong&gt;安全与数字意识&lt;/strong&gt; 系列 旨在推广负责任且富有教育意义的做法 �围绕自由工具。&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_介绍&quot;&gt;介绍&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_1_版本目录_libs_versions_toml_一个提醒&quot;&gt;1. 版本目录 (&lt;code&gt;libs.versions.toml&lt;/code&gt;) : 一个提醒&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_问题复合构建与两个独立的世界&quot;&gt;2. 问题：复合构建与两个独立的世界&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_解决方案共享依赖解析&quot;&gt;3. 解决方案：共享依赖解析&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_结论管理良好的组合构建的力量&quot;&gt;4. 结论：管理良好的组合构建的力量&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_介绍&quot;&gt;介绍&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;目标受众：面对多项目构建依赖管理挑战的 Gradle 开发者。&lt;/div&gt;
&lt;p&gt;在我们创建插件的追求中`site-baker`我们一直致力于保持代码库的整洁和集中化。现代 Gradle 生态系统中最佳实践之一是使用&lt;strong&gt;版本目录&lt;/strong&gt;(&lt;code&gt;libs.versions.toml&lt;/code&gt;) 用于管理依赖项。但是当你的项目变得更复杂时，会发生什么情况，例如一个&lt;strong&gt;构建复合&lt;/strong&gt;在哪里需要将一个独立的构建（我们的插件）包含在另一个构建中？&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;正是在这里，我们的冒险迎来了意想不到的转折。我们希望我们的插件`site-baker`, 它本身是一个 Gradle 项目，使用与我们主项目相同的版本目录。本文是我们系列的第五篇，讲述了我们如何解决了这个挑战。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_1_版本目录_libs_versions_toml_一个提醒&quot;&gt;1. 版本目录 (&lt;code&gt;libs.versions.toml&lt;/code&gt;) : 一个提醒&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;文件`gradle/libs.versions.toml`是Gradle的一项功能，用于集中管理项目依赖的版本和坐标。它通常被结构为四个部分：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;[versions]&lt;/code&gt;: 为版本号定义别名（例如：&lt;code&gt;kotlin = &quot;1.9.20&quot;&lt;/code&gt;).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;[libraries]`定义完整依赖项的别名，使用上面定义的版本 （例如：`kotlin-stdlib = { module = &quot;org.jetbrains.kotlin:kotlin-stdlib&quot;, version.ref = &quot;kotlin&quot; }&lt;/code&gt;).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;[bundles]&lt;/code&gt;: 将多个库归组到一个别名下 (ex:`jackson = [&quot;jackson-core&quot;, &quot;jackson-databind&quot;]`).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;[plugins]&lt;/code&gt;: 为 Gradle 插件设置别名。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;一旦定义，Gradle 会自动生成类型化的访问器，这使得您的`build.gradle.kts`更易读：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;dependencies {
    // Au lieu de : implementation(&quot;org.jetbrains.kotlin:kotlin-stdlib:1.9.20&quot;)
    implementation(libs.kotlin.stdlib)
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;版本目录的数据流&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme plain
file &quot;gradle/libs.versions.toml&quot; as Toml
node &quot;Gradle&quot; as G
file &quot;build.gradle.kts&quot; as BuildScript

Toml --&amp;gt; G : &quot;被读&quot;
G --&amp;gt; BuildScript : &quot;生成访问器 `libs&quot;
BuildScript -&amp;gt; G : &quot;使用 `libs` 来声明依赖&quot;
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_2_问题复合构建与两个独立的世界&quot;&gt;2. 问题：复合构建与两个独立的世界&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;我们的项目结构是一个&lt;strong&gt;构建复合体&lt;/strong&gt;. 主要项目 (&lt;code&gt;thymeleaf.cheroliv.com&lt;/code&gt;) 包含插件项目 (&lt;code&gt;site-baker&lt;/code&gt;) 通过命令`includeBuild(&quot;site-baker&quot;)&lt;code&gt;在文件中`settings.gradle.kts&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;复合构建的结构&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme plain
package &quot;主要项目&quot; {
  file &quot;settings.gradle.kts&quot; as MainSettings
  folder &quot;格雷德尔&quot; {
    file &quot;libs.versions.toml&quot; as MainToml
  }
}

package &quot;插件 `site-baker` (包含的构建)&quot; {
  file &quot;settings.gradle.kts&quot; as PluginSettings
  file &quot;build.gradle.kts&quot; as PluginBuild
}

MainSettings -&amp;gt; PluginSettings : `includeBuild(&quot;site-baker&quot;)`
PluginBuild ..&amp;gt; MainToml : **Voulait accéder à...**
note right on link: ...mais ne pouvait pas !
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;问题是，默认情况下，一个包含的构建是一个&lt;strong&gt;独立的世界&lt;/strong&gt;. 它有自己的配置，自己的生命周期，并且它看不到该文件`libs.versions.toml`主构建。 我们的`plugin/build.gradle.kts`试图使用`libs.plugins.kotlin.jvm`, 但该对象`libs`它不是从正确的 TOML 文件生成的，导致构建错误。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_3_解决方案共享依赖解析&quot;&gt;3. 解决方案：共享依赖解析&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;经过多次研究，解决方案被证明是Gradle专为这种情况设计的功能：&lt;code&gt;dependencyResolutionManagement&lt;/code&gt;。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;在文件中`settings.gradle.kts` du &lt;strong&gt;构建包容&lt;/strong&gt;(&lt;code&gt;site-baker/settings.gradle.kts&lt;/code&gt;), 我们可以告诉 Gradle 在哪里找到要使用的版本目录。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;以下是我们添加的配置`site-baker/settings.gradle.kts`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// site-baker/settings.gradle.kts

dependencyResolutionManagement {
    repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS)
    repositories {
        gradlePluginPortal()
        mavenCentral()
    }
    versionCatalogs {
        create(&quot;libs&quot;) {
            from(files(&quot;../gradle/libs.versions.toml&quot;))
        }
    }
}

rootProject.name = &quot;site-baker&quot;
include(&quot;plugin&quot;)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;让我们分析关键部分 :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;versionCatalogs {
    create(&quot;libs&quot;) { // Crée un catalogue nommé &#39;libs&#39;
        from(files(&quot;../gradle/libs.versions.toml&quot;)) // En utilisant ce fichier
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;create(&quot;libs&quot;)&lt;/code&gt;: 我们声明一个版本目录，将可通过别名访问`libs`。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;from(files(&quot;../gradle/libs.versions.toml&quot;))&lt;/code&gt;: 这就是魔法。我们告诉 Gradle 此目录的来源是位于该目录下的 TOML 文件`gradle` du &lt;strong&gt;父项目&lt;/strong&gt;(&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&amp;lt;/think&amp;gt; (&lt;code&gt;../&lt;/code&gt;)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;使用此配置，构建`site-baker`现在他知道他必须使用主项目的版本目录。对象`libs`已正确生成，并且依赖关系按预期解决。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_4_结论管理良好的组合构建的力量&quot;&gt;4. 结论：管理良好的组合构建的力量&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;这段经历非常充实。版本目录是提高可维护性的绝佳工具，但在复合构建场景中的行为并不总是直观。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;关键是要记住，被包含的构建仍然是一个独立的构建。要共享诸如版本目录之类的配置，必须使用 Gradle 提供的显式机制，例如代码块。&lt;code&gt;dependencyResolutionManagement`在`settings.gradle.kts&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;通过解决此问题，我们不仅使构建更加整洁，还增强了项目的一致性，确保插件和主项目共享唯一的事实来源来管理它们的依赖项。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;在下一篇文章中，我们将在现有插件的基础上继续添加更复杂的任务来丰富它，因为现在我们的依赖管理已经很稳固且集中。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_引言&quot;&gt;引言&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_症状幽灵构建&quot;&gt;�症状：幽灵构建&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_调查配置缓存是什么&quot;&gt;调查：配置缓存是什么？&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_问题的原因不合规的插件&quot;&gt;问题的原因：不合规的插件&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_临时解决方案禁用缓存&quot;&gt;临时解决方案：禁用缓存&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_真正的解决方案使插件兼容&quot;&gt;真正的解决方案：使插件兼容&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_引言&quot;&gt;引言&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;目标受众：Gradle开发者曾经遇到过&amp;#8217;神奇的&amp;#8217;或意外的构建行为.&lt;/div&gt;
&lt;p&gt;在我们创建插件的历程中`site-baker`, 我们遵循了严格的TDD方法。每个功能都进行了测试、验证，并且我们充满信心地前进。然后有一天，意外到来。构建开始表现得反复无常。插件逻辑或配置文件的修改似乎被忽略，而我们之前可靠的功能测试莫名其妙地失败了。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;这种问题可能会令人极度沮丧。它质疑了工具的可靠性和我们代码的有效性。经过一次激烈的调试会话后，罪魁祸首被确定为：&lt;strong&gt;Gradle 配置缓存&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_症状幽灵构建&quot;&gt;�症状：幽灵构建&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;问题以多种方式表现出来：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;我在一项任务中修改字符串`println`, 但旧的字符串在运行时仍然显示。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;我当时正在更改我的文件中的一个值`managed-jbake-context.yml`, 但插件的行为就像文件没有被修改一样。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;功能测试会即时创建测试项目，但它们失败了，因为插件似乎没有检测到新创建的配置文件。&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;一切都好像 Gradle 在执行我们构建的一个“幻影版本”，忽略了我们最近的更改。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_调查配置缓存是什么&quot;&gt;调查：配置缓存是什么？&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;配置缓存是 Gradle 相对现代且功能极其强大的特性，在新版本中默认启用。其目标是让构建更快。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;div class=&quot;title&quot;&gt;原则很简单：&lt;/div&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;在第一次执行时，Gradle 执行阶段&lt;strong&gt;配置&lt;/strong&gt;( 读取 的)&lt;code&gt;build.gradle.kts&lt;/code&gt;, 创建任务，解析依赖) 并构建任务图。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;在此阶段结束时，Gradle&lt;strong&gt;序列化此任务图&lt;/strong&gt;并将其缓存。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;在随后的执行中，如果没有任何更改（构建脚本`gradle.properties`, etc.), Gradle&lt;strong&gt;完全跳过配置阶段&lt;/strong&gt;并重新使用缓存的任务图。&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;在大型项目中，时间节约效果惊人。然而，这种性能有代价：它对插件的编写方式提出了严格的要求。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;配置缓存的生命周期&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start
:Première exécution;
:Phase de Configuration;
:Création du graphe de tâches;
:Mise en cache du graphe;
:Phase d&#39;Exécution;
end

start
:Exécution suivante;
if (Cache valide ?) then (oui)
  :Restauration du graphe depuis le cache;
  note right
    La phase de configuration
    est sautée !
  end note
else (non)
  :Phase de Configuration;
  :Mise à jour du cache;
endif
:Phase d&#39;Exécution;
stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_问题的原因不合规的插件&quot;&gt;问题的原因：不合规的插件&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;我们的插件`site-baker`不知不觉地违反了配置缓存的若干规则。 为了使任务图可序列化，任务不得包含对复杂对象（如对象）的引用`Project`或以任意方式读取文件，在执行阶段。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;我们的主要错误是在任务执行逻辑内直接读取 YAML 文件的内容，使用我们扩展中存储的路径引用。这种方法与缓存不兼容，因为如果这种读取未被建模为一个，Gradle 无法知道文件内容是否已更改。&lt;strong&gt;任务条目&lt;/strong&gt;(任务输入).&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_临时解决方案禁用缓存&quot;&gt;临时解决方案：禁用缓存&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;为了使我们摆脱困境并恢复可预测的构建行为，最快的解决方案是禁用配置缓存。只需在文件中添加以下行即可。&lt;code&gt;gradle.properties`使用该插件的项目（或者在我们的情况下，是测试项目）`site-baker&lt;/code&gt;).&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# site-baker/gradle.properties
org.gradle.configuration-cache=false&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;瞬间，构建恢复了正常行为。每次执行都重新启动了配置阶段，我们的更改被考虑在内。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;然而，这是一个变通的解决方案，而不是一个持久的解决方案。它牺牲了性能，也没有解决我们插件的根本问题。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_真正的解决方案使插件兼容&quot;&gt;真正的解决方案：使插件兼容&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;为了让插件成为现代 Gradle 生态系统的良好公民，它必须与配置缓存兼容。这意味着我们需要重新思考数据如何流向我们的任务。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;关键是使用&lt;strong&gt;提供方 API&lt;/strong&gt;Gradle的。 而不是直接传递值（如一个)&lt;code&gt;String&lt;/code&gt; ou un &lt;code&gt;File&lt;/code&gt;) 对于我们的任务，我们必须花费`Property&amp;lt;T&amp;gt;`或一些`Provider&amp;lt;T&amp;gt;`。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;div class=&quot;title&quot;&gt;以下是重构计划：&lt;/div&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;声明任务条目：&lt;/strong&gt;解析 YAML 文件的任务必须将该文件声明为输入。为此，我们使用该注解。&lt;code&gt;@InputFile&lt;/code&gt;。&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;[source,kotlin] ---- @get:InputFile abstract val configFile: RegularFileProperty ----&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_介绍&quot;&gt;介绍&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_1_上下文我们的插件_site_baker&quot;&gt;1. 上下文：我们的插件 `site-baker&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_kotlin_中的配置建模&quot;&gt;2. Kotlin 中的配置建模&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_在_build_gradle_kts_中集成_jackson&quot;&gt;3. 在 &lt;code&gt;build.gradle.kts&lt;/code&gt; 中集成 Jackson&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_tdd方法测试yaml解析&quot;&gt;4. TDD方法：测试YAML解析&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_4_1_单元测试_将_yaml_映射为_kotlin_对象&quot;&gt;4.1. 单元测试 : 将 YAML 映射为 Kotlin 对象&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_2_功能测试验证配置文件的读取&quot;&gt;4.2. 功能测试：验证配置文件的读取&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_5_解析流可视化&quot;&gt;5. 解析流可视化&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_结论&quot;&gt;结论&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;&lt;em&gt;阅读时间 :&lt;/em&gt; 12 分钟。&lt;/div&gt;
&lt;p&gt;目标受众：希望管理复杂配置的中级 Gradle 开发者。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_介绍&quot;&gt;介绍&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;在开发Gradle插件时，管理复杂配置是一项常见任务。与其在DSL中堆砌数百个属性，不如将配置定义在外部文件中（如YAML）更为简洁且易于维护。本文将引导您使用强大的Jackson库将YAML文件解析为Kotlin对象，并采用严格的TDD方法以确保插件的健壮性。&lt;code&gt;site-baker&lt;/code&gt;。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_1_上下文我们的插件_site_baker&quot;&gt;1. 上下文：我们的插件 `site-baker&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;我们的插件`site-baker`旨在自动化静态站点的生成和部署。它需要读取一个 YAML 配置文件 (&lt;code&gt;managed-jbake-context.yml&lt;/code&gt;) 以获取诸如源代码路径、部署目标和 Git 标识符等信息。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;我们希望解析的YAML配置看起来像这样：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-yaml hljs&quot; data-lang=&quot;yaml&quot;&gt;bake:
  srcPath: &quot;./site/jbake&quot;
  destDirPath: &quot;bake&quot;
  cname: &quot;cheroliv.com&quot;
pushPage:
  from: &quot;bake&quot;
  to: &quot;cvs&quot;
  repo:
    name: &quot;trainings&quot;
    repository: &quot;https://github.com/pages-content/pages-content.github.io.git&quot;
    credentials:
      username: &quot;USERNAME&quot;
      password: &quot;SECRET_TOKEN&quot;
  branch: &quot;main&quot;
  message: &quot;cheroliv.com&quot;
# ... autres configurations (pushMaquette, supabase, etc.)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_2_kotlin_中的配置建模&quot;&gt;2. Kotlin 中的配置建模&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;在解析之前，我们需要用 Kotlin 定义数据的结构。Jackson 将使用这些类自动映射 YAML 内容。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/src/main/kotlin/com/cheroliv/site/baker/data/SiteConfiguration.kt
package com.cheroliv.site.baker.data

import com.fasterxml.jackson.databind.ObjectMapper
import com.fasterxml.jackson.dataformat.yaml.YAMLFactory
import com.fasterxml.jackson.module.kotlin.readValue
import com.fasterxml.jackson.module.kotlin.registerKotlinModule

fun parseSiteConfiguration(yaml: String): SiteConfiguration {
    val mapper = ObjectMapper(YAMLFactory()).registerKotlinModule()
    return mapper.readValue(yaml)
}

data class GitPushConfiguration(
    val from: String = &quot;&quot;,
    val to: String = &quot;&quot;,
    val repo: RepositoryConfiguration = RepositoryConfiguration(),
    val branch: String = &quot;&quot;,
    val message: String = &quot;&quot;,
)

data class RepositoryConfiguration(
    val name: String = &quot;&quot;,
    val repository: String = &quot;&quot;,
    val credentials: RepositoryCredentials = RepositoryCredentials(),
) {
    companion object {
        const val ORIGIN = &quot;origin&quot;
        const val CNAME = &quot;CNAME&quot;
        const val REMOTE = &quot;remote&quot;
    }
}

data class RepositoryCredentials(val username: String = &quot;&quot;, val password: String = &quot;&quot;)

data class SiteConfiguration(
    val bake: BakeConfiguration = BakeConfiguration(),
    val pushPage: GitPushConfiguration = GitPushConfiguration(),
    val pushMaquette: GitPushConfiguration = GitPushConfiguration(),
    val pushSource: GitPushConfiguration? = null,
    val pushTemplate: GitPushConfiguration? = null,
    val supabase: SupabaseContactFormConfig? = null
)

data class BakeConfiguration(
    val srcPath: String = &quot;&quot;,
    val destDirPath: String = &quot;&quot;,
    val cname: String? = null,
)

// ... (autres data classes pour Supabase, si nécessaire)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;函数`parseSiteConfiguration`这是我们的反序列化入口点。它使用`ObjectMapper`Jackson 的, 配置为`YAMLFactory`用于 YAML 格式和`registerKotlinModule()`用于支持 Kotlin 的特性（如属性的默认值）。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_3_在_build_gradle_kts_中集成_jackson&quot;&gt;3. 在 &lt;code&gt;build.gradle.kts&lt;/code&gt; 中集成 Jackson&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;要使用 Jackson，我们需要在 中添加必要的依赖项`build.gradle.kts`我们的模块的`plugin`[Empty string]&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/build.gradle.kts
dependencies {
    // Jackson for YAML parsing
    implementation(&quot;com.fasterxml.jackson.module:jackson-module-kotlin:2.18.3&quot;)
    implementation(&quot;com.fasterxml.jackson.dataformat:jackson-dataformat-yaml:2.18.3&quot;)

    // ... autres dépendances
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;我们使用`jackson-module-kotlin`用于 Kotlin 支持和`jackson-dataformat-yaml`用于管理 YAML 格式。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_4_tdd方法测试yaml解析&quot;&gt;4. TDD方法：测试YAML解析&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;现在，让我们应用TDD来验证我们的解析逻辑。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_1_单元测试_将_yaml_映射为_kotlin_对象&quot;&gt;4.1. 单元测试 : 将 YAML 映射为 Kotlin 对象&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;我们从单元测试开始，在`SiteBakerPluginTest.kt`为验证该函数`parseSiteConfiguration`可以正确地将 YAML 字符串转换为对象`SiteConfiguration`。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/src/test/kotlin/com/cheroliv/site/baker/SiteBakerPluginTest.kt
@Test
fun `can map configuration text to SiteConfiguration object`() {
    val yamlString = &quot;../../managed-jbake-context.yml&quot;
        .run(::File)
        .readText()
        .trimIndent()

    val config: SiteConfiguration = parseSiteConfiguration(yamlString)

    assertEquals(&quot;cheroliv.com&quot;, config.bake.cname)
    assertEquals(&quot;main&quot;, config.pushPage.branch)
    assertEquals(&quot;https://github.com/pages-content/pages-content.github.io.git&quot;, config.pushPage.repo.repository)
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;此测试读取文件的内容`managed-jbake-context.yml`(必须存在才能使测试有效)并对对象执行断言`SiteConfiguration`生成的。它验证 YAML 中的键值是否正确映射。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_2_功能测试验证配置文件的读取&quot;&gt;4.2. 功能测试：验证配置文件的读取&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;为了确保插件能够通过其 DSL 读取配置文件，并且在真实的 Gradle 环境中解析正常工作，我们添加了一个功能测试到`SiteBakerPluginFunctionalTest.kt`。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;此测试至关重要，因为它在真实项目中模拟了插件的执行。它必须&lt;strong&gt;密封的&lt;/strong&gt;, 也就是说，他必须自己创建该文件`managed-jbake-context.yml`� 带有受控内容，以确保测试的可重复性和隔离性。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/src/functionalTest/kotlin/com/cheroliv/site/baker/SiteBakerPluginFunctionalTest.kt
@Test
fun `config file contains good data`(){
    val configContent = configFile.readText(UTF_8)
    // Vérifications comme dans vos commentaires
    assertTrue(configContent.contains(&quot;bake&quot;))
    assertTrue(configContent.contains(&quot;pushPage&quot;))
    assertTrue(configContent.contains(&quot;repository&quot;))
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;此功能测试验证复制到测试临时目录的配置文件包含预期的数据。尽管此测试不会直接将 YAML 解析为 Kotlin 对象，但它验证了文件及其内容的存在，这是插件解析之前必不可少的前置步骤。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_5_解析流可视化&quot;&gt;5. 解析流可视化&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;下图说明了在解析YAML配置时的数据流和交互：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
actor &quot;Gradle用户&quot; as User
participant &quot;build.gradle.kts&quot; as BuildScript
participant &quot;SiteBakerPlugin&quot; as Plugin
participant &quot;站点扩展&quot; as Extension
participant &quot;managed-jbake-context.yml&quot; as ConfigFile
participant &quot;解析站点配置()&quot; as Parser
participant &quot;SiteConfiguration (Kotlin 对象)&quot; as KotlinObject

User -&amp;gt; BuildScript : Applique le plugin et configure le DSL
BuildScript -&amp;gt; Plugin : apply()
Plugin -&amp;gt; Extension : Crée et enregistre l&#39;extension &#39;site&#39;
User -&amp;gt; BuildScript : site { configPath = &quot;...&quot; }
BuildScript -&amp;gt; Extension : Définit configPath

Plugin -&amp;gt; ConfigFile : Lit le fichier (via configPath)
ConfigFile --&amp;gt; Plugin : Contenu YAML
Plugin -&amp;gt; Parser : Appelle parseSiteConfiguration(yamlString)
Parser -&amp;gt; KotlinObject : Mappe le YAML en objet SiteConfiguration
KotlinObject --&amp;gt; Plugin : Retourne l&#39;objet configuré

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_结论&quot;&gt;结论&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;通过采用 TDD 方法，我们成功地在 Gradle 插件中集成了 Jackson 库，以将 YAML 配置文件解析为 Kotlin 对象。此方法使我们能够：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;清晰地建模&lt;/strong&gt;我们的配置使用 Kotlin 数据类。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;验证解析逻辑&lt;/strong&gt;带有有针对性的单元测试。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;确保集成&lt;/strong&gt;在真实的 Gradle 环境中，通过密闭的功能测试。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;这个坚实的基础让我们有信心在插件上扩展功能，这些功能建立在此配置之上，同时保证代码的可维护性和健壮性。YAML 解析现在已成为我们插件的一个可靠且经过测试的功能。&lt;code&gt;site-baker&lt;/code&gt;。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table of Contents&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_项目初始化&quot;&gt;项目初始化&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_我们的首个_tdd_周期记录一项任务&quot;&gt;2. 我们的首个 TDD 周期：记录一项任务&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_2_1_首先测试失败的测试&quot;&gt;2.1. 首先测试（失败的测试）&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_2_代码随后使测试通过&quot;&gt;2.2. 代码随后（使测试通过）&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_tdd_第二阶段添加_dsl_扩展&quot;&gt;3. TDD 第二阶段：添加 DSL 扩展&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_3_1_首先测试&quot;&gt;3.1. 首先测试&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_2_接下来的代码&quot;&gt;3.2. 接下来的代码&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_功能测试验证集成&quot;&gt;4. 功能测试：验证集成&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_4_1_集成测试创建受控环境&quot;&gt;4.1. 集成测试：创建受控环境&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_2_完成逻辑&quot;&gt;4.2. 完成逻辑&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_结论&quot;&gt;结论&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;在本文中，我们将探讨如何使用测试驱动开发（TDD - Test-Driven Development）的方法为 Gradle 插件建立一个坚实的开发基础。 这种方法确保我们的代码是健壮、可维护的，并且能够从一开始就精确满足需求。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_项目初始化&quot;&gt;项目初始化&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Gradle 通过命令大大简化了创建新插件的过程。&lt;code&gt;gradle init&lt;/code&gt;. 选择使用 Kotlin 创建一个 &quot;Gradle Plugin&quot;，我们将得到一个即用型项目结构，其中包含两种关键的测试类型：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;单元测试 :&lt;/strong&gt;位于`src/test`, 它们允许验证我们插件的隔离组件，例如任务的内部逻辑或扩展的配置。它们速度快，不需要完整的 Gradle 执行。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;功能测试：&lt;/strong&gt;位于`src/functionalTest`, 他们使用`GradleRunner`为了在临时测试项目中执行完整的Gradle构建。这使我们能够在受控环境中验证插件的实际行为。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_2_我们的首个_tdd_周期记录一项任务&quot;&gt;2. 我们的首个 TDD 周期：记录一项任务&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;我们的第一个要求很简单：插件必须记录一个已命名的任务。&lt;code&gt;printSiteConfig&lt;/code&gt;。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_1_首先测试失败的测试&quot;&gt;2.1. 首先测试（失败的测试）&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;根据 TDD，我们首先编写一个测试来验证该任务的存在。在`SiteBakerPluginTest.kt`(我们的单元测试文件)，我们添加：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test
fun `plugin registers task`() {
    // Créer un projet de test en mémoire
    val project = ProjectBuilder.builder().build()
    project.plugins.apply(&quot;com.cheroliv.site-baker&quot;)

    // Vérifier que la tâche a bien été enregistrée
    assertNotNull(project.tasks.findByName(&quot;printSiteConfig&quot;))
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;此测试失败，因为我们尚未在插件中编写任何代码。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_2_代码随后使测试通过&quot;&gt;2.2. 代码随后（使测试通过）&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;现在，我们写所需的最少代码在`SiteBakerPlugin.kt`让测试通过:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;class SiteBakerPlugin: Plugin&amp;lt;Project&amp;gt; {
    override fun apply(project: Project) {
        // Enregistrer une tâche simple
        project.tasks.register(&quot;printSiteConfig&quot;) { task -&amp;gt;
            // ... la logique de la tâche viendra plus tard
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;我们重新运行测试，它们通过了。我们的第一个功能已被验证。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_3_tdd_第二阶段添加_dsl_扩展&quot;&gt;3. TDD 第二阶段：添加 DSL 扩展&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;接下来的要求是允许用户通过一个 DSL 块在其配置我们的插件`build.gradle.kts`. 我们想要一个块`site { &amp;#8230;&amp;#8203; }`可以指定配置路径的地方。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_3_1_首先测试&quot;&gt;3.1. 首先测试&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;我们添加一个测试来验证扩展`site`它已正确记录，且可为其赋予一个值。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test
fun `plugin registers extension`() {
    val project = ProjectBuilder.builder().build()
    project.plugins.apply(&quot;com.cheroliv.site-baker&quot;)

    // Récupérer l&#39;extension et lui affecter une valeur
    project.extensions
        .findByType(SiteExtension::class.java)!!
        .configPath
        .set(&quot;config.yml&quot;)

    // Vérifier que la valeur a bien été prise en compte
    assertEquals(
        &quot;config.yml&quot;,
        project.extensions.findByType(SiteExtension::class.java)?.configPath?.get()
    )
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;此测试失败，因为既不该类`SiteExtension`也不存在扩展的注册&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_3_2_接下来的代码&quot;&gt;3.2. 接下来的代码&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;我们正在创建该类`SiteBakerExtension.kt`和我们更新`SiteBakerPlugin.kt`：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// SiteBakerExtension.kt
open class SiteExtension @Inject constructor(objects: ObjectFactory) {
    val configPath: Property&amp;lt;String&amp;gt; = objects.property(String::class.java)
}

// SiteBakerPlugin.kt
class SiteBakerPlugin: Plugin&amp;lt;Project&amp;gt; {
    override fun apply(project: Project) {
        // Enregistrer l&#39;extension
        val extension = project.extensions.create(&quot;site&quot;, SiteExtension::class.java)

        project.tasks.register(&quot;printSiteConfig&quot;) { task -&amp;gt;
            task.doLast {
                // On utilisera l&#39;extension plus tard
            }
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;�测试再次通过。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_4_功能测试验证集成&quot;&gt;4. 功能测试：验证集成&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;既然单元已经测试完毕，我们必须确保它们在真实构建中能够协同工作。这就是功能测试的作用在`SiteBakerPluginFunctionalTest.kt`。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_1_集成测试创建受控环境&quot;&gt;4.1. 集成测试：创建受控环境&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;这个测试将模拟使用我们插件的真实项目。为了让它可靠，它必须&lt;strong&gt;密封的&lt;/strong&gt;, 换句话说，它不应依赖于系统上已存在的文件。它必须自己创建执行所需的所有条件。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;�测试将因此 :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;创建一个`build.gradle.kts`使用我们的插件及其DSL的测试&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;创建配置文件&lt;/strong&gt;(&lt;code&gt;managed-jbake-context.yml&lt;/code&gt;) 插件应该读取的内容。这是测试稳健性的一步关键步骤。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;执行任务`printSiteConfig`经过`GradleRunner`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;� 检查构建输出是否正确。&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;通过在每次执行时复制或创建此配置文件，我们确保测试是&lt;strong&gt;可重复&lt;/strong&gt;并且不依赖于外部状态。这可以保护我们的测试免受与文件读取相关的回归问题的影响。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test fun `can run task with DSL`() {
    // 1. Créer un build.gradle.kts de test
    buildFile.writeText(&quot;&quot;&quot;
        plugins { id(&quot;com.cheroliv.site-baker&quot;) }
        site { configPath = &quot;managed-jbake-context.yml&quot; }
    &quot;&quot;&quot;.trimIndent())

    // 2. Créer le fichier de configuration pour un test contrôlé
    val configFile = File(projectDir, &quot;managed-jbake-context.yml&quot;)
    configFile.writeText(&quot;site: { title: &#39;Mon Site de Test&#39; }&quot;) // Contenu YAML simple

    // 3. Exécuter la build
    val runner = GradleRunner.create()
    runner.withPluginClasspath()
    runner.withArguments(&quot;printSiteConfig&quot;)
    runner.withProjectDir(projectDir) // Spécifier le répertoire du projet de test
    val result = runner.build()

    // 4. Vérifier la sortie
    assertTrue(result.output.contains(&quot;Site config path: managed-jbake-context.yml&quot;))
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;此测试将在任务未完成时一直失败`printSiteConfig`它不会真的使用扩展的值。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_2_完成逻辑&quot;&gt;4.2. 完成逻辑&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;我们正在更新任务在`SiteBakerPlugin.kt`为了使它显示配置的值 :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;project.tasks.register(&quot;printSiteConfig&quot;) { task -&amp;gt;
    task.doLast {
        println(&quot;Site config path: ${extension.configPath.get()}&quot;)
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;所有测试，单元测试和功能测试，现在都通过了。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_结论&quot;&gt;结论&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;采用TDD方法，我们以增量且安全的方式构建了一个插件。每个小功能都会立即通过测试进行验证，从快速的单元测试到验证完整集成的功能测试。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;通过确保我们的测试是功能性的&lt;strong&gt;密封的&lt;/strong&gt;— 例如，通过以编程方式创建必要的配置文件 —  — 我们构建了一个极其健壮的安全网。这种严谨性能够有效防止回归，并使我们有足够信心随后添加更复杂的功能，如解析 YAML 配置文件。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;这个坚实的测试基础是维护和插件未来发展最宝贵的资产。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_引言&quot;&gt;引言&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_步骤_1_启动项目助手&quot;&gt;步骤 1 : 启动项目助手&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_步骤_2理解生成的结构&quot;&gt;步骤 2：理解生成的结构&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_关键文件和文件夹&quot;&gt;关键文件和文件夹&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_引言&quot;&gt;引言&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;目标受众：从初级到中级的 Gradle 开发者。&lt;/div&gt;
&lt;p&gt;启动一个新的 Gradle 插件项目可能会让人感到望而生畏。幸运的是，Gradle 提供了一个强大的交互式助手，任务`init`, 它生成一个完整、干净且可直接使用的项目结构。本指南将向您展示如何使用此工具创建健康的插件基础，解释其结构，并演示如何启动初始的构建任务。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_步骤_1_启动项目助手&quot;&gt;步骤 1 : 启动项目助手&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;命令`gradle init`是起点。它启动一个命令行助手，会向您提出一系列问题以配置项目。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;在空文件夹中打开终端并执行：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gradle init&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;助手会为您指引。以下是为使用 Kotlin 编写的 Gradle 插件所需做出的选择：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;选择要生成的项目类型：&lt;/strong&gt;选择`Gradle plugin`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;选择实现语言：&lt;/strong&gt;选择`Kotlin`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;选择构建脚本DSL:&lt;/strong&gt;选择`Kotlin`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;项目名称:&lt;/strong&gt;请输入您的项目名称 （例如：&lt;code&gt;site-baker&lt;/code&gt;).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;插件 ID:&lt;/strong&gt;为您的插件提供一个唯一的标识符 （例如：&lt;code&gt;com.cheroliv.site-baker&lt;/code&gt;)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;�插件类：&lt;/strong&gt;请指定实现类的名称 (例如：&lt;code&gt;com.cheroliv.SiteBakerPlugin&lt;/code&gt;).&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;完成后，Gradle 生成完整的文件树。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;初始化过程的图表&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start
:Lancer `gradle init`;
:Choisir &quot;Gradle 插件&quot;;
:Choisir &quot;Kotlin&quot; (langage);
:Choisir &quot;Kotlin&quot; (DSL);
:Saisir nom, ID, et classe;
:Projet généré;
stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_步骤_2理解生成的结构&quot;&gt;步骤 2：理解生成的结构&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;助手创建了一个多模块项目结构，将根项目与插件本身的源代码分开。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;.
├── gradle/
│   └── wrapper/
│       ├── gradle-wrapper.jar
│       └── gradle-wrapper.properties
├── gradlew
├── gradlew.bat
├── plugin/
│   ├── build.gradle.kts
│   └── src/
│       ├── main/
│       │   └── kotlin/
│       │       └── com/cheroliv/SiteBakerPlugin.kt
│       ├── test/
│       │   └── kotlin/
│       │       └── com/cheroliv/SiteBakerPluginTest.kt
│       └── functionalTest/
│           └── kotlin/
│               └── com/cheroliv/SiteBakerPluginFunctionalTest.kt
└── settings.gradle.kts&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_关键文件和文件夹&quot;&gt;关键文件和文件夹&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;settings.gradle.kts&lt;/code&gt;: 此根目录文件定义了构建中包含的模块。在这里，它包含了子项目。&lt;code&gt;plugin&lt;/code&gt;。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;[source,kotlin] (empty) rootProject.name = &quot;site-baker include(&quot;plugin&quot;) ----&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_简介&quot;&gt;简介&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_1_jdkgradle_的引擎&quot;&gt;1. JDK：Gradle 的引擎&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_选择哪个版本&quot;&gt;选择哪个版本？&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_通过_sdkman_安装推荐&quot;&gt;通过 SDKMAN! 安装（推荐）&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_安装_sdkman&quot;&gt;安装 SDKMAN！&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_安装_jdk_版本&quot;&gt;安装 JDK 版本&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_检查安装&quot;&gt;检查安装&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ideintellij_idea&quot;&gt;IDE：IntelliJ IDEA&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_gradle构建工具&quot;&gt;3. Gradle：构建工具&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_通过_sdkman_安装&quot;&gt;通过 SDKMAN! 安装&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_安装_gradle&quot;&gt;安装 Gradle&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_检查安装_2&quot;&gt;检查安装&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_jbake_静态站点生成器&quot;&gt;4. JBake : 静态站点生成器&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_通过sdkman_安装&quot;&gt;通过SDKMAN! 安装&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_安装_jbake&quot;&gt;安装 JBake&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_检查安装_3&quot;&gt;&lt;strong&gt;检查安装&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_5_gradle_包装器绝对的最佳实践&quot;&gt;5. Gradle 包装器：绝对的最佳实践&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_6_docker_和_portainer实现可重复构建可选&quot;&gt;6. Docker 和 Portainer：实现可重复构建（可选）&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_docker_engine_安装&quot;&gt;Docker Engine 安装&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_通过官方脚本安装_docker&quot;&gt;&lt;strong&gt;通过官方脚本安装 Docker :&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_管理_docker_不使用_sudo推荐&quot;&gt;管理 Docker 不使用 &lt;code&gt;sudo&lt;/code&gt;（推荐）：&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_使用_portainer_gui_管理_docker&quot;&gt;使用 Portainer (GUI) 管理 Docker&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_创建一个用于_portainer_数据的卷&quot;&gt;&lt;strong&gt;创建一个用于 Portainer 数据的卷 :&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_启动_portainer_容器&quot;&gt;启动 Portainer 容器：&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_结论&quot;&gt;结论&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_简介&quot;&gt;简介&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;目标受众 : 希望开始创建 Gradle 插件的开发者。&lt;/div&gt;
&lt;p&gt;要高效地开发 Gradle 插件，一个配置良好的开发环境是必不可少的。 良好的设置会为您节省时间，减少挫败感，并确保您的构建保持一致。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;div class=&quot;title&quot;&gt;本指南专注于四个关键支柱：&lt;/div&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Le &lt;strong&gt;Java 开发工具包&lt;/strong&gt;（Java Development Kit），因为 Gradle 和 JBake 在 JVM 上运行。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Un &lt;strong&gt;集成开发环境&lt;/strong&gt;使用现代化的 IntelliJ IDEA，对 Kotlin 和 Gradle 提供了良好的支持。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Gradle&lt;/strong&gt;他自己，为了初始化项目。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;JBake&lt;/strong&gt;, 我们静态网站的引擎。&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;开发环境的组件&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme plain
node &quot;开发者机器&quot; {
  component &quot;JDK（JVM）&quot; as JDK
  component &quot;IntelliJ IDEA&quot; as IDE
  component &quot;Gradle (全局)&quot; as Gradle
  component &quot;JBake (全球)&quot; as JBake

  IDE --&amp;gt; JDK : utilise
  Gradle --&amp;gt; JDK : utilise
  JBake --&amp;gt; JDK : utilise
}
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_1_jdkgradle_的引擎&quot;&gt;1. JDK：Gradle 的引擎&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Gradle 是一个运行在 Java虚拟机(JVM) 上的应用程序。 因此，安装 JDK 是绝对的前置条件。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_选择哪个版本&quot;&gt;选择哪个版本？&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;建议使用 Java 的长期支持（LTS）版本。 目前，&lt;strong&gt;JDK 17&lt;/strong&gt; ou &lt;strong&gt;JDK 21&lt;/strong&gt;是很好的选择。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_通过_sdkman_安装推荐&quot;&gt;通过 SDKMAN! 安装（推荐）&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;SDKMAN！ 是管理众多 SDK 版本（包括 Java 和 Gradle）的绝佳工具。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_安装_sdkman&quot;&gt;安装 SDKMAN！&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;curl -s &quot;https://get.sdkman.io&quot; | bash source &quot;$HOME/.sdkman/bin/sdkman-init.sh&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_安装_jdk_版本&quot;&gt;安装 JDK 版本&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Pour lister les versions de Java disponibles sdk list java

# Pour installer Java 17 (par exemple, la distribution Temurin)
sdk install java 17.0.8-tem&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_检查安装&quot;&gt;检查安装&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;java -version&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;您应该能看到您刚刚安装的版本显示出来。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ideintellij_idea&quot;&gt;IDE：IntelliJ IDEA&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;用于使用 Kotlin DSL 开发 Gradle 插件，&lt;strong&gt;IntelliJ IDEA&lt;/strong&gt;是首选工具。 其与Gradle和Kotlin的集成无与伦比。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;社区版：&lt;/strong&gt;免费且足够充裕，可以开始。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;终极版：&lt;/strong&gt;付费版，它提供了用于Web开发和数据库的高级功能。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;从JetBrains网站下载适合您的版本：https://www.jetbrains.com/idea/download/&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;IDE 将自动检测您的文件`build.gradle.kts` et &lt;code&gt;settings.gradle.kts&lt;/code&gt;, 提供强大的自动补全、代码导航和集成调试工具。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_3_gradle构建工具&quot;&gt;3. Gradle：构建工具&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;虽然每个项目都会通过 Gradle Wrapper 使用其自己的 Gradle 版本，但拥有全局 Gradle 安装对于诸如初始化新项目之类的任务仍然很有用 （&lt;code&gt;gradle init&lt;/code&gt;)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_通过_sdkman_安装&quot;&gt;通过 SDKMAN! 安装&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;同样如同 JDK，SDKMAN! 简化了 Gradle 的安装。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_安装_gradle&quot;&gt;安装 Gradle&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;sdk install gradle&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_检查安装_2&quot;&gt;检查安装&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gradle -v&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;此命令将显示所使用的 Gradle、Kotlin、Groovy 和 JDK 版本。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_4_jbake_静态站点生成器&quot;&gt;4. JBake : 静态站点生成器&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;JBake 是我们将用来将源文件（如这个）转换为静态网站的工具。 �拥有本地安装对于预览更改很方便。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_通过sdkman_安装&quot;&gt;通过SDKMAN! 安装&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;与其他工具一样，SDKMAN! 是最简单的方法。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_安装_jbake&quot;&gt;安装 JBake&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;sdk install jbake&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_检查安装_3&quot;&gt;&lt;strong&gt;检查安装&lt;/strong&gt;&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;jbake -v&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;此命令将显示 JBake 的版本及其使用的 Java 环境信息。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_5_gradle_包装器绝对的最佳实践&quot;&gt;5. Gradle 包装器：绝对的最佳实践&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;创建您的项目后（我们将在下一篇文章中介绍），您不应该再使用全局命令。&lt;code&gt;gradle&lt;/code&gt;. 您将使用&lt;strong&gt;Gradle 包装器&lt;/strong&gt; (&lt;code&gt;./gradlew&lt;/code&gt;), 一个包含在您的项目中的脚本。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;为什么？&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;可重复性：&lt;/strong&gt;Wrapper 确保项目中的每个人（包括您的 CI/CD 服务器）都使用完全相同的&lt;strong&gt;相同版本的 Gradle&lt;/strong&gt;, 从而消除了由于不同环境导致的构建错误。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;简洁：&lt;/strong&gt;不需要手动安装 Gradle 即可为项目做出贡献。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;只需克隆仓库并启动`./gradlew`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;一个典型的命令将如下所示：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Ne pas faire : gradle build
# À faire :
./gradlew build&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_6_docker_和_portainer实现可重复构建可选&quot;&gt;6. Docker 和 Portainer：实现可重复构建（可选）&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;虽然在编写插件时并非严格必需，但 Docker 和 Portainer 是现代的 DevOps 工具，极大地便利了创建可重现的构建以及管理您的环境。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_docker_engine_安装&quot;&gt;Docker Engine 安装&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Docker 允许您将应用程序及其依赖项打包到一个容器中。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_通过官方脚本安装_docker&quot;&gt;&lt;strong&gt;通过官方脚本安装 Docker :&lt;/strong&gt;&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;curl -fsSL https://get.docker.com -o get-docker.sh sudo sh get-docker.sh&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_管理_docker_不使用_sudo推荐&quot;&gt;管理 Docker 不使用 &lt;code&gt;sudo&lt;/code&gt;（推荐）：&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;将您的用户添加到组`docker`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;sudo usod -aG docker $USER&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock important&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-important&quot; title=&quot;Important&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;

&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;docker run hello-world&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_使用_portainer_gui_管理_docker&quot;&gt;使用 Portainer (GUI) 管理 Docker&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Portainer 是一个轻量级的 Web 界面，用于管理您的 Docker 容器。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_创建一个用于_portainer_数据的卷&quot;&gt;&lt;strong&gt;创建一个用于 Portainer 数据的卷 :&lt;/strong&gt;&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;docker volume create portainer_data&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_启动_portainer_容器&quot;&gt;启动 Portainer 容器：&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;docker run -d -p 8000:8000 -p 9443:9443 --name portainer --restart=always -v /var/run/docker.sock:/var/run/docker.sock -v portainer_data:/data portainer/portainer-ce:latest&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;您现在可以访问Portainer界面在`https://localhost:9443`.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_结论&quot;&gt;结论&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;您的环境现在已准备好！ 您�拥有 JDK、最合适的 IDE、Gradle 和 JBake。 加入 Docker 后，您也已准备好创建容器化且可复现的构建。 这个坚实的基础将让你能够专注于本质：开发强大而实用的插件。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;在下一篇文章中，我们将使用该命令`gradle init`用于生成我们第一个插件项目的结构。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table of Contents&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_与_poetry_集成&quot;&gt;与 Poetry 集成&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_安装_poetry&quot;&gt;安装 Poetry&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_项目初始化&quot;&gt;项目初始化&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_添加和安装依赖&quot;&gt;�添加和安装依赖&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_使用_poetry_进行发布&quot;&gt;使用 Poetry 进行发布&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_可复现的_docker_构建&quot;&gt;可复现的 Docker 构建&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_dockerfile_示例&quot;&gt;Dockerfile 示例&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_在_github_actions_中的集成&quot;&gt;在 GitHub Actions 中的集成&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_条件发布&quot;&gt;条件发布&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_使用_renovate_和_dependabot_自动化依赖&quot;&gt;使用 Renovate 和 Dependabot 自动化依赖&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_dependabot&quot;&gt;Dependabot&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_翻新&quot;&gt;翻新&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_plantuml_图表&quot;&gt;PlantUML 图表&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_用例_高级_cicd&quot;&gt;用例 – 高级 CI/CD&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_序列_有条件发布&quot;&gt;序列 – 有条件发布&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_状态_cicd_管道&quot;&gt;状态 – CI/CD 管道&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_部署_cicd_架构&quot;&gt;部署 – CI/CD 架构&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_结论&quot;&gt;结论&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;在这系列的前两部分中，我们有： - 建立了一个可用于 Python 应用的 CI/CD 流水线，使用 GitHub Actions 和 PyPI。 - 已将此流水线工业化，使用多版本测试、通过 Test PyPI 进行渐进式发布，并配备质量和安全工具。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;在这第三部分，我们将会去&lt;strong&gt;超越在 PyPI 上的简单发布&lt;/strong&gt;为了构建一个完整、健壮且专业的 CI/CD 流水线，配有： - &lt;strong&gt;诗歌&lt;/strong&gt;为了现代化的包装和依赖的优化管理。 - &lt;strong&gt;Docker&lt;/strong&gt;为了创建可重复且跨平台的构建。 - &lt;strong&gt;条件发布&lt;/strong&gt;用于处理诸如候选发布版之类的场景。 - &lt;strong&gt;自动化工具&lt;/strong&gt;(Renovate, Dependabot) 轻松保持管道最新。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_与_poetry_集成&quot;&gt;与 Poetry 集成&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Poetry 通过集中管理依赖和构建，取代了旧的打包工具（setup.py, requirements.txt）&lt;code&gt;pyproject.toml&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_安装_poetry&quot;&gt;安装 Poetry&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-shell hljs&quot; data-lang=&quot;shell&quot;&gt;# Installer Poetry
curl -sSL https://install.python-poetry.org | python3 -
# Vérifier la version
poetry --version&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_项目初始化&quot;&gt;项目初始化&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-shell hljs&quot; data-lang=&quot;shell&quot;&gt;# Initialiser un nouveau projet avec Poetry
poetry init
# Suivre l&#39;assistant pour renseigner : nom, version, description, licence, dépendances.&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;这会生成一个文件`pyproject.toml` :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-toml hljs&quot; data-lang=&quot;toml&quot;&gt;[tool.poetry]
name = &quot;playlist-downloader&quot;
version = &quot;0.1.0&quot;
description = &quot;CLI tool for managing YouTube playlists&quot;
authors = [&quot;Christophe Hérolivier &amp;lt;cheroliv@example.com&amp;gt;&quot;]

[tool.poetry.dependencies]
python = &quot;&amp;gt;=3.8&quot;
typer = &quot;^0.9.0&quot;
yt-dlp = &quot;^2023.7.6&quot;
google-api-python-client = &quot;^2.0.0&quot;
google-auth-oauthlib = &quot;^1.0.0&quot;

[tool.poetry.group.dev.dependencies]
pytest = &quot;^7.0&quot;
mypy = &quot;^1.0&quot;
bandit = &quot;^1.7&quot;
safety = &quot;^2.3&quot;
black = &quot;^23.0&quot;
ruff = &quot;^0.1&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_添加和安装依赖&quot;&gt;�添加和安装依赖&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-shell hljs&quot; data-lang=&quot;shell&quot;&gt;poetry add typer yt-dlp google-api-python-client google-auth-oauthlib
poetry add --group dev pytest mypy black bandit safety ruff&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_使用_poetry_进行发布&quot;&gt;使用 Poetry 进行发布&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Poetry 原生管理发布：&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-shell hljs&quot; data-lang=&quot;shell&quot;&gt;# Publication sur Test PyPI
poetry publish --build --repository test-pypi

# Publication sur PyPI
poetry publish --build&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;此命令会自动使用存在于&amp;#8230;&amp;#8203;中的信息`pyproject.toml`.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_可复现的_docker_构建&quot;&gt;可复现的 Docker 构建&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;为确保在开发、CI/CD 和生产环境中实现一致的执行，Docker 与 Poetry 完全集成。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_dockerfile_示例&quot;&gt;Dockerfile 示例&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-dockerfile hljs&quot; data-lang=&quot;dockerfile&quot;&gt;FROM python:3.11-slim

WORKDIR /app
COPY pyproject.toml poetry.lock ./
RUN pip install poetry
RUN poetry install --no-root --only main

COPY . .

CMD [&quot;poetry&quot;, &quot;run&quot;, &quot;python&quot;, &quot;cli.py&quot;]&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;这确保： - 一个固定的 Python 环境。 - 已锁定的依赖项通过`poetry.lock`. - 可在所有支持 Docker 的系统上运行的可执行镜像。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_在_github_actions_中的集成&quot;&gt;在 GitHub Actions 中的集成&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-yaml hljs&quot; data-lang=&quot;yaml&quot;&gt;name: Docker Build

on:
  push:
    branches: [main]

jobs:
  build-docker:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - name: Build Docker image
        run: docker build -t ghcr.io/${{ github.repository }}:latest .
      - name: Push Docker image
        run: docker push ghcr.io/${{ github.repository }}:latest&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_条件发布&quot;&gt;条件发布&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;在专业流水线中，必须能够仅在某些情况下发布： - 发布候选版本至 Test PyPI 将稳定版本发布到 PyPI。 - 仅触发的 Docker 构建用于`main`。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-yaml hljs&quot; data-lang=&quot;yaml&quot;&gt;- name: Publish to Test PyPI
  if: contains(github.ref, &#39;-rc&#39;)
  run: poetry publish --build --repository test-pypi

- name: Publish to PyPI
  if: startsWith(github.ref, &#39;refs/tags/v&#39;)
  run: poetry publish --build&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;这种方法可以避免意外发布。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_使用_renovate_和_dependabot_自动化依赖&quot;&gt;使用 Renovate 和 Dependabot 自动化依赖&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;为了防止您的依赖变得过时，请集成自动更新工具。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_dependabot&quot;&gt;Dependabot&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-yaml hljs&quot; data-lang=&quot;yaml&quot;&gt;version: 2
updates:
  - package-ecosystem: &quot;pip&quot;
    directory: &quot;/&quot;
    schedule:
      interval: &quot;weekly&quot;
  - package-ecosystem: &quot;github-actions&quot;
    directory: &quot;/&quot;
    schedule:
      interval: &quot;weekly&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dependabot 每周创建 PR 以更新 Python 和 GitHub Actions 依赖。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_翻新&quot;&gt;翻新&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-json hljs&quot; data-lang=&quot;json&quot;&gt;{
  &quot;extends&quot;: [&quot;config:base&quot;],
  &quot;packageRules&quot;: [
    {
      &quot;matchManagers&quot;: [&quot;pip&quot;],
      &quot;groupName&quot;: &quot;python-dependencies&quot;,
      &quot;schedule&quot;: [&quot;before 6am on monday&quot;]
    }
  ]
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Renovate 允许进行更细粒度的控制：依赖分组、调度以及高级规则。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_plantuml_图表&quot;&gt;PlantUML 图表&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_用例_高级_cicd&quot;&gt;用例 – 高级 CI/CD&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
actor Developer
actor GitHub as &quot;GitHub Actions&quot;
actor PyPI
actor DockerRegistry as &quot;Docker 注册表&quot;
actor Automation as &quot;Renovate/Dependabot&quot;

Developer --&amp;gt; (Push code)
(Trigger CI) --&amp;gt; GitHub
GitHub --&amp;gt; (Run Tests &amp;amp; Lint)
GitHub --&amp;gt; (Build Docker Image)
GitHub --&amp;gt; DockerRegistry
GitHub --&amp;gt; (Publish to Test PyPI)
GitHub --&amp;gt; (Promote to PyPI)
Automation --&amp;gt; (Update Dependencies)
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_序列_有条件发布&quot;&gt;序列 – 有条件发布&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme vibrant
left to right direction
Developer -&amp;gt; GitHub: Push tag v1.2.3-rc
GitHub -&amp;gt; CI: Run tests
CI -&amp;gt; CD: Check release type
CD -&amp;gt; Test PyPI: Publish RC
Developer -&amp;gt; GitHub: Push tag v1.2.3
GitHub -&amp;gt; CD: Publish to PyPI
CD -&amp;gt; Docker Registry: Push Docker image
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_状态_cicd_管道&quot;&gt;状态 – CI/CD 管道&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
[*] --&amp;gt; Idle
Idle --&amp;gt; CI_Running : push
CI_Running --&amp;gt; CI_Success : tests ok
CI_Running --&amp;gt; CI_Failed : tests fail
CI_Success --&amp;gt; CD_Running : tag detected
CD_Running --&amp;gt; CD_Success : publish ok
CD_Running --&amp;gt; CD_Failed : error
CD_Success --&amp;gt; [*]
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_部署_cicd_架构&quot;&gt;部署 – CI/CD 架构&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
node &quot;开发者机器&quot; {
  component &quot;Git 客户端&quot;
}

node &quot;GitHub Actions&quot; {
  component &quot;CI 工作流&quot;
  component &quot;CD 工作流程&quot;
}

node &quot;�软件包仓库&quot; {
  artifact &quot;�测试 PyPI&quot;
  artifact &quot;PyPI&quot;
  artifact &quot;Docker 注册表&quot;
}

&quot;开发者机器&quot; --&amp;gt; &quot;GitHub Actions&quot;
&quot;GitHub Actions&quot; --&amp;gt; &quot;�测试 PyPI&quot;
&quot;GitHub Actions&quot; --&amp;gt; &quot;PyPI&quot;
&quot;GitHub Actions&quot; --&amp;gt; &quot;Docker 注册表&quot;
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_结论&quot;&gt;结论&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;在这第三部分中，我们了解了如何： - 使用 Poetry 现代化 Python 包装。 - 通过Docker确保构建可重现。 - 设置条件性发布. 自动化依赖项的更新。&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;您现在拥有了一个 CI/CD 管道&lt;strong&gt;完整、工业化和安全&lt;/strong&gt;, 准备好随着您的项目发展。&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
