&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#Google Apps Script 中的类型和变量&quot;&gt;[Google Apps Script 中的类型和变量]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#常量、变量和在 Google Apps Script 中的字母&quot;&gt;[常量、变量和在 Google Apps Script 中的字母]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#Google Apps Script 中的操作和运算符&quot;&gt;[Google Apps Script 中的操作和运算符]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#Var、Let 和 Const 在 Google Apps Script 中&quot;&gt;[Var、Let 和 Const 在 Google Apps Script 中]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#Google Apps Script 中的控制结构&quot;&gt;[Google Apps Script 中的控制结构]&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#_google_apps_script_中的循环&quot;&gt;Google Apps Script 中的循环&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#_google_apps_script_中的对象&quot;&gt;Google Apps Script 中的对象&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
